-- =============================================================================
-- FICHIER GÉNÉRÉ par infra/scripts/build-exam-seed.mjs à partir de db/content/exam-banks.mjs.
-- Ne pas modifier à la main : modifier db/content/exam-banks/*.mjs puis relancer le script.
--
-- 204 questions d'examen relues (linux 36, network 24, docker 24, security 24, windows 48, devops 14, kubernetes 10, postgresql 24). Rejouable : le contenu du dépôt fait
-- foi et réécrit une question existante (même identifiant), sauf son état de relecture : une question
-- retirée par un administrateur (reviewed = false) le reste.
-- =============================================================================
INSERT INTO assessment.questions (id, type, prompt_md, choices, answer, explanation, difficulty, platform, generated_by_ai, reviewed)
SELECT (q->>'id')::uuid, q->>'type', q->>'prompt', q->'choices', q->'answer', q->>'explanation',
       (q->>'difficulty')::platform.difficulty, (q->>'platform')::platform.os_platform, false, true
  FROM (VALUES
    ($q${"id":"5405d5bf-df2d-5e83-bf2f-70028c3edf55","type":"single","prompt":"Un service ne démarre plus et `df -h` montre `/var` à 100 %. Quelle est la première chose à faire ?","choices":[{"id":"a","text":"Redémarrer le serveur pour libérer de l'espace"},{"id":"b","text":"Identifier ce qui occupe la place avec du -sh /var/*, avant de supprimer quoi que ce soit"},{"id":"c","text":"Supprimer tout le contenu de /var/log"},{"id":"d","text":"Agrandir la partition immédiatement"}],"answer":["b"],"explanation":"On mesure avant d'agir : du montre quel répertoire a grossi. Vider /var/log efface des preuves et peut casser des services ; redémarrer ne libère pas un fichier présent sur disque ; agrandir traite le symptôme sans connaître la cause.","difficulty":"intermediate","platform":"linux"}$q$::jsonb),
    ($q${"id":"e4956b19-1893-5553-856b-8cb55bb92db6","type":"single","prompt":"Pourquoi vider un gros journal avec `truncate -s 0 fichier` plutôt que de le supprimer avec `rm` quand un processus l'écrit encore ?","choices":[{"id":"a","text":"Parce que rm d'un fichier ouvert ne libère pas l'espace tant que le processus le garde ouvert"},{"id":"b","text":"Il n'y a aucune différence"},{"id":"c","text":"Parce que rm est interdit sur les fichiers de /var/log"},{"id":"d","text":"Parce que truncate compresse le fichier"}],"answer":["a"],"explanation":"Un fichier supprimé mais encore ouvert reste sur le disque (visible avec lsof +L1) jusqu'à la fermeture. truncate garde le même fichier et libère l'espace tout de suite ; il ne compresse rien.","difficulty":"intermediate","platform":"linux"}$q$::jsonb),
    ($q${"id":"c21e3cdc-1120-55e3-9d46-45a4846dd5f7","type":"single","prompt":"`systemctl start nginx` échoue et le journal indique « bind() to 0.0.0.0:80 failed (98: Address already in use) ». Quelle commande confirme la cause ?","choices":[{"id":"a","text":"df -h"},{"id":"b","text":"chmod 755 /etc/nginx"},{"id":"c","text":"ss -tlnp | grep :80"},{"id":"d","text":"systemctl enable nginx"}],"answer":["c"],"explanation":"Le message dit qu'un autre processus écoute déjà le port 80 : ss -tlnp montre lequel. df concerne l'espace disque, chmod les droits, et enable ne fait que préparer le démarrage au boot.","difficulty":"beginner","platform":"linux"}$q$::jsonb),
    ($q${"id":"6d9c0f6d-e6a5-5f12-bfca-0a9c26246bed","type":"single","prompt":"Quelle est la différence entre `systemctl enable` et `systemctl start` ?","choices":[{"id":"a","text":"enable lance le service maintenant et au boot"},{"id":"b","text":"Ce sont deux synonymes"},{"id":"c","text":"start rend le démarrage permanent"},{"id":"d","text":"enable prépare le démarrage automatique au boot, start lance le service maintenant"}],"answer":["d"],"explanation":"enable crée les liens qui feront démarrer le service au prochain boot, sans le lancer ; start le lance tout de suite sans rien rendre permanent. enable --now combine les deux.","difficulty":"beginner","platform":"linux"}$q$::jsonb),
    ($q${"id":"9080f81b-bce5-5a7d-afec-d1851a685421","type":"multiple","prompt":"Un fichier `.env` contenant un mot de passe est en mode 644, propriétaire root, groupe www-data. L'application tourne sous www-data. Cochez toutes les affirmations justes.","choices":[{"id":"a","text":"chmod 640 garde la lecture pour www-data et la retire aux autres"},{"id":"b","text":"chmod 777 réglerait le problème"},{"id":"c","text":"Tous les comptes du serveur peuvent le lire"},{"id":"d","text":"chmod 600 est plus sûr et l'application continuera de fonctionner"}],"answer":["a","c"],"explanation":"644 donne la lecture aux « autres ». 640 la réserve au propriétaire (root) et au groupe www-data. 600 la retirerait aussi au groupe : l'application ne pourrait plus lire sa configuration. 777 aggraverait tout.","difficulty":"intermediate","platform":"linux"}$q$::jsonb),
    ($q${"id":"151c15b5-7d68-589f-8fbc-59e02d293d99","type":"single","prompt":"Dans `ls -l`, que signifie `-rw-r-----` ?","choices":[{"id":"a","text":"Le propriétaire lit et écrit, le groupe lit, les autres n'ont aucun droit"},{"id":"b","text":"Le propriétaire n'a que la lecture"},{"id":"c","text":"Le fichier est exécutable par le groupe"},{"id":"d","text":"Tout le monde peut lire, seul le propriétaire écrit"}],"answer":["a"],"explanation":"Les trois triplets se lisent propriétaire, groupe, autres : rw- (lecture, écriture), r-- (lecture), --- (rien). C'est le mode 640.","difficulty":"beginner","platform":"linux"}$q$::jsonb),
    ($q${"id":"b837630b-bff7-5a9f-a48e-797af5351dc0","type":"single","prompt":"Après une migration, `ping 10.0.0.1` répond mais `ping depot.exemple.fr` affiche « Temporary failure in name resolution ». Que regarder en premier ?","choices":[{"id":"a","text":"La table de routage"},{"id":"b","text":"Le serveur DNS configuré dans /etc/resolv.conf"},{"id":"c","text":"La carte réseau"},{"id":"d","text":"Le pare-feu local"}],"answer":["b"],"explanation":"Le réseau fonctionne (une adresse IP répond) : c'est la résolution de noms qui échoue. Le routage, le pare-feu et la carte sont déjà mis hors de cause par le ping réussi vers l'IP.","difficulty":"beginner","platform":"linux"}$q$::jsonb),
    ($q${"id":"e4cf40c9-0105-54cf-9ec9-4fbad462eebf","type":"single","prompt":"Pourquoi `journalctl -u nom-du-service` est-il souvent plus utile que `systemctl status` pour comprendre un échec ?","choices":[{"id":"a","text":"Il corrige automatiquement l'erreur"},{"id":"b","text":"Il montre l'historique complet des messages du service, pas seulement les dernières lignes"},{"id":"c","text":"Il affiche la configuration du service"},{"id":"d","text":"Il redémarre le service en mode débogage"}],"answer":["b"],"explanation":"systemctl status résume l'état et quelques lignes ; journalctl -u donne tous les messages du service (avec -n, -f ou --since pour filtrer). Il ne redémarre et ne corrige rien.","difficulty":"beginner","platform":"linux"}$q$::jsonb),
    ($q${"id":"37b3a90b-1e1a-50e3-a12e-9e12fb8a3609","type":"single","prompt":"Vous devez modifier une ligne dans un fichier de configuration critique sur un serveur en production. Quelle démarche est la plus sûre ?","choices":[{"id":"a","text":"Sauvegarder le fichier, modifier, vérifier la syntaxe (ex. nginx -t), puis recharger le service"},{"id":"b","text":"Modifier directement puis redémarrer le serveur"},{"id":"c","text":"Modifier et attendre le prochain redémarrage planifié"},{"id":"d","text":"Supprimer le fichier et laisser le paquet le recréer"}],"answer":["a"],"explanation":"Une copie permet de revenir en arrière, la vérification de syntaxe évite de couper le service, et un reload applique sans interruption. Redémarrer tout le serveur ou supprimer la configuration est disproportionné et risqué.","difficulty":"intermediate","platform":"linux"}$q$::jsonb),
    ($q${"id":"b46341b1-0ec2-5108-a1bd-5ce7e6b3e15d","type":"multiple","prompt":"Une route par défaut ajoutée avec `ip route add default via 10.0.0.1` répare le réseau. Cochez toutes les affirmations justes.","choices":[{"id":"a","text":"Elle sera perdue au prochain redémarrage si elle n'est pas écrite dans la configuration réseau"},{"id":"b","text":"Elle ne prend effet qu'après un redémarrage"},{"id":"c","text":"Elle est enregistrée automatiquement dans /etc/network/interfaces"},{"id":"d","text":"Il faut aussi la déclarer dans la configuration (gateway, netplan…) pour qu'elle dure"}],"answer":["a","d"],"explanation":"ip route modifie la table du noyau immédiatement mais en mémoire seulement : rien n'est écrit sur le disque. Pour que la correction survive au redémarrage, elle doit figurer dans la configuration du réseau.","difficulty":"intermediate","platform":"linux"}$q$::jsonb),
    ($q${"id":"ea46bffe-2c6f-52bb-8ec7-b8190662b458","type":"single","prompt":"Un utilisateur demande `chmod -R 777 /var/www` « pour que ça marche ». Que répondre ?","choices":[{"id":"a","text":"Accepter mais seulement la nuit"},{"id":"b","text":"Refuser : chercher quel compte doit accéder à quoi et donner le droit minimal"},{"id":"c","text":"Utiliser 666 à la place, c'est équivalent mais plus sûr"},{"id":"d","text":"Accepter, c'est la solution standard"}],"answer":["b"],"explanation":"777 donne l'écriture à tous les comptes : n'importe quel processus compromis pourrait modifier le site. On identifie le compte du service (www-data) et on accorde le droit minimal nécessaire.","difficulty":"beginner","platform":"linux"}$q$::jsonb),
    ($q${"id":"0dafd69c-1219-549a-a20c-ae4666e31d41","type":"single","prompt":"Quel signal indique qu'un service a été tué faute de mémoire ?","choices":[{"id":"a","text":"Un code de sortie 0"},{"id":"b","text":"Le service apparaît « enabled »"},{"id":"c","text":"Un fichier core dans /etc"},{"id":"d","text":"Un message « Out of memory: Killed process … » dans le journal du noyau (journalctl -k ou dmesg)"}],"answer":["d"],"explanation":"L'OOM killer du noyau journalise le processus qu'il termine. Un code 0 signifie une fin normale ; « enabled » ne concerne que le démarrage au boot.","difficulty":"intermediate","platform":"linux"}$q$::jsonb),
    ($q${"id":"cfd87096-2bda-536e-b587-3d896573496e","type":"single","prompt":"La charge moyenne (load average) d’un serveur à 8 cœurs est de 24, mais le processeur est à 15 % d’utilisation. Quelle piste explorer d’abord ?","choices":[{"id":"a","text":"Un manque de cœurs : la charge dépasse leur nombre"},{"id":"b","text":"Un problème de DNS"},{"id":"c","text":"Un processeur trop lent, à remplacer"},{"id":"d","text":"Des processus bloqués en attente d’entrées-sorties (état D), visibles avec vmstat (colonne wa) ou iostat"}],"answer":["d"],"explanation":"Sous Linux, la charge compte aussi les processus en attente non interruptible, souvent sur le disque ou un montage réseau. Un CPU peu utilisé avec une charge élevée oriente vers les entrées-sorties : vmstat montre le temps d’attente (wa), iostat -x la saturation par disque.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"a8d12eb5-5d97-552f-8d1d-29d16391bac8","type":"single","prompt":"`free -h` montre seulement 200 Mo « free » sur 32 Go, mais 20 Go « available ». Le serveur manque-t-il de mémoire ?","choices":[{"id":"a","text":"Oui, il faut vider le cache avec echo 3 > /proc/sys/vm/drop_caches toutes les heures"},{"id":"b","text":"Non : le noyau utilise la mémoire libre comme cache de fichiers et la rend dès qu’une application en a besoin ; « available » est l’indicateur à suivre"},{"id":"c","text":"Oui, il faut ajouter de la mémoire immédiatement"},{"id":"d","text":"Non, car la mémoire libre n’est jamais utilisée"}],"answer":["b"],"explanation":"La mémoire inutilisée est gaspillée : Linux s’en sert comme cache de pages. « available » estime ce qui peut être alloué sans échanger. Vider le cache régulièrement ne fait que dégrader les performances, car les fichiers doivent être relus sur le disque.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"18f23735-5973-547c-a7a8-24ddeda2e87f","type":"single","prompt":"Un service critique est régulièrement tué par l’OOM killer lors des pics, alors qu’un traitement par lots peu important consomme beaucoup de mémoire. Quelle réponse est la plus adaptée ?","choices":[{"id":"a","text":"Ajouter du swap jusqu’à ce que cela passe"},{"id":"b","text":"Redémarrer le serveur chaque nuit"},{"id":"c","text":"Désactiver l’OOM killer du noyau"},{"id":"d","text":"Limiter la mémoire du traitement par lots (MemoryMax= dans son unité systemd, donc son cgroup) et protéger le service (OOMScoreAdjust= négatif)"}],"answer":["d"],"explanation":"On contient le consommateur et on oriente le choix du noyau. Sans OOM killer, le système entier se figerait sous la pression ; un swap démesuré rend la machine inutilisable ; un redémarrage programmé ne traite pas la cause.","difficulty":"expert","platform":"linux"}$q$::jsonb),
    ($q${"id":"0249b8ec-5714-59d6-8bb2-20d7f6b714c8","type":"single","prompt":"Comment surcharger un réglage d’une unité systemd fournie par un paquet sans modifier son fichier dans /usr/lib/systemd/system ?","choices":[{"id":"a","text":"En modifiant directement le fichier du paquet"},{"id":"b","text":"En copiant l’unité dans /tmp"},{"id":"c","text":"En renommant le service"},{"id":"d","text":"Avec `systemctl edit nom.service`, qui crée un fichier d’override dans /etc/systemd/system/nom.service.d/, puis recharger"}],"answer":["d"],"explanation":"Les fichiers sous /usr appartiennent au paquet et seraient écrasés à la mise à jour. Les drop-ins de /etc s’ajoutent au fichier d’origine et ne contiennent que ce qui change. systemctl edit recharge la configuration automatiquement ; sinon, systemctl daemon-reload.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"d64683eb-87e7-5a9d-a398-4726d96e8edc","type":"single","prompt":"Que fait `Restart=on-failure` avec `StartLimitBurst=5` et `StartLimitIntervalSec=60` dans une unité systemd ?","choices":[{"id":"a","text":"Le service ne redémarre que 5 fois au total, pour toujours"},{"id":"b","text":"Le service redémarre toutes les 60 secondes"},{"id":"c","text":"systemd relance le service s’il échoue, mais abandonne après 5 démarrages en 60 secondes et le laisse en échec"},{"id":"d","text":"Le service est arrêté s’il consomme plus de 5 % du CPU"}],"answer":["c"],"explanation":"La limite de démarrage évite qu’un service mal configuré tourne en boucle. Une fois atteinte, l’unité reste « failed » jusqu’à systemctl reset-failed ou un démarrage manuel : on lit le journal pour comprendre avant de relancer.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"5c4df265-5350-5c82-8f7a-47b929d4bbbb","type":"single","prompt":"Quel est l’avantage d’agrandir un volume logique LVM plutôt qu’une partition classique ?","choices":[{"id":"a","text":"LVM double automatiquement les performances"},{"id":"b","text":"LVM rend les données inaltérables"},{"id":"c","text":"LVM remplace la sauvegarde"},{"id":"d","text":"On peut l’étendre à chaud sur l’espace libre du groupe de volumes, même réparti sur plusieurs disques, puis agrandir le système de fichiers"}],"answer":["d"],"explanation":"lvextend puis resize2fs (ext4) ou xfs_growfs (XFS) agrandissent sans démonter. LVM n’est ni une sauvegarde ni un mécanisme de redondance : un snapshot LVM est sur les mêmes disques que les données.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"8823ac64-500c-55bb-a444-cb2c3623f51a","type":"single","prompt":"Vous devez réduire un système de fichiers XFS de 500 Go à 300 Go. Que savoir ?","choices":[{"id":"a","text":"Il suffit de lvreduce, XFS s’adapte"},{"id":"b","text":"XFS ne peut pas être réduit : il faut sauvegarder, recréer un volume plus petit et restaurer"},{"id":"c","text":"xfs_growfs accepte une taille plus petite"},{"id":"d","text":"XFS se réduit automatiquement quand des fichiers sont supprimés"}],"answer":["b"],"explanation":"XFS ne sait que grandir. Réduire le volume logique sous un XFS détruirait le système de fichiers. ext4 peut être réduit hors ligne avec resize2fs, toujours avant lvreduce et après une sauvegarde.","difficulty":"expert","platform":"linux"}$q$::jsonb),
    ($q${"id":"c8ba0b0b-e61a-5b72-bc53-7966ff940444","type":"single","prompt":"Un RAID 1 logiciel (mdadm) affiche `[U_]` dans /proc/mdstat. Que faire ?","choices":[{"id":"a","text":"Rien, U_ signifie que tout va bien"},{"id":"b","text":"Recréer la grappe avec mdadm --create"},{"id":"c","text":"Formater le disque restant"},{"id":"d","text":"Un disque est sorti de la grappe : identifier lequel, vérifier son état (smartctl), le remplacer et l’ajouter à la grappe pour la reconstruire"}],"answer":["d"],"explanation":"U_ indique un membre actif et un manquant : la grappe fonctionne en mode dégradé, sans redondance. On remplace rapidement le disque (mdadm --add) et on suit la reconstruction. mdadm --create sur des disques existants peut détruire les données.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"bf6dedb3-71ff-5840-a7d7-374952faad1f","type":"single","prompt":"Pourquoi un RAID ne remplace-t-il pas une sauvegarde ?","choices":[{"id":"a","text":"Parce qu’il est plus lent qu’une sauvegarde"},{"id":"b","text":"Parce qu’il ne fonctionne qu’avec deux disques"},{"id":"c","text":"Parce qu’il réplique aussi les suppressions, les corruptions et le chiffrement par un rançongiciel ; il ne protège que d’une panne de disque"},{"id":"d","text":"Il la remplace, c’est la même chose"}],"answer":["c"],"explanation":"Le RAID assure la disponibilité face à la perte d’un disque. Une erreur humaine ou logicielle est appliquée aussitôt à tous les membres. Une sauvegarde garde des versions passées, ailleurs et idéalement hors ligne.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"5af51394-2c4d-5593-b241-db9c14fe03c6","type":"single","prompt":"Dans un cluster Pacemaker à deux nœuds, pourquoi le fencing (STONITH) est-il indispensable ?","choices":[{"id":"a","text":"Pour chiffrer la communication entre nœuds"},{"id":"b","text":"Pour économiser l’énergie du nœud inactif"},{"id":"c","text":"Pour accélérer la bascule"},{"id":"d","text":"Pour qu’un nœud qui ne répond plus soit réellement arrêté avant que l’autre reprenne ses ressources, ce qui évite que les deux écrivent sur les mêmes données (split brain)"}],"answer":["d"],"explanation":"Un nœud injoignable n’est pas forcément arrêté : il peut écrire encore sur le stockage partagé. Le fencing le coupe (gestion d’alimentation, carte IPMI) avant la reprise. Sans lui, une coupure réseau peut corrompre les données.","difficulty":"expert","platform":"linux"}$q$::jsonb),
    ($q${"id":"18508e82-847f-5ce7-80c3-1f0ead64cd83","type":"single","prompt":"Que garantit une adresse IP virtuelle gérée par keepalived (VRRP) devant deux répartiteurs de charge ?","choices":[{"id":"a","text":"Que l’adresse reste servie : si le répartiteur actif tombe, l’autre reprend l’adresse en quelques secondes"},{"id":"b","text":"Que les données des applications sont répliquées"},{"id":"c","text":"Que le trafic est chiffré"},{"id":"d","text":"Que la charge est partagée moitié-moitié entre les deux"}],"answer":["a"],"explanation":"VRRP élit un maître qui porte l’adresse virtuelle ; un secondaire la reprend s’il n’entend plus le maître. C’est une bascule active-passive de l’adresse, pas un partage de charge ni une réplication de données.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"cbfa8c64-52d6-5db4-8be1-22793446ae79","type":"single","prompt":"Pourquoi un playbook Ansible doit-il être idempotent ?","choices":[{"id":"a","text":"Pour pouvoir le rejouer sans risque : il ne change que ce qui n’est pas déjà dans l’état voulu, et le résultat est le même à chaque exécution"},{"id":"b","text":"Pour qu’il ne s’exécute qu’une seule fois dans la vie du serveur"},{"id":"c","text":"Pour qu’il s’exécute plus vite la première fois"},{"id":"d","text":"Parce qu’Ansible refuse les playbooks non idempotents"}],"answer":["a"],"explanation":"Les modules décrivent un état (paquet présent, ligne dans un fichier) plutôt qu’une action. Un shell: non conditionné relance sa commande à chaque fois : on lui ajoute creates:, changed_when: ou on préfère un module dédié.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"21aaf0ba-0e7b-5a09-9606-9d0a21549b97","type":"single","prompt":"Avant d’appliquer un playbook Ansible sur 300 serveurs de production, que faire ?","choices":[{"id":"a","text":"Le lancer directement sur les 300 serveurs pour gagner du temps"},{"id":"b","text":"Se connecter à chaque serveur pour vérifier à la main avant"},{"id":"c","text":"Le lancer en mode vérification (--check --diff) puis sur un petit groupe, et utiliser serial pour avancer par lots"},{"id":"d","text":"Désactiver la gestion des erreurs"}],"answer":["c"],"explanation":"--check --diff montre ce qui changerait, un groupe pilote valide le résultat réel, et serial limite l’ampleur d’une erreur (max_fail_percentage arrête le déploiement). Lancer partout d’un coup transforme une erreur en panne générale.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"24fd07ad-d9b8-5610-a122-94525f1ffb7f","type":"single","prompt":"SELinux bloque un serveur web qui doit lire des fichiers placés dans /srv/site. Quelle correction est la bonne ?","choices":[{"id":"a","text":"Passer les fichiers en 777"},{"id":"b","text":"Désactiver SELinux"},{"id":"c","text":"Donner le bon contexte au répertoire (semanage fcontext -a -t httpd_sys_content_t \"/srv/site(/.*)?\" puis restorecon -R /srv/site)"},{"id":"d","text":"Lancer le serveur web en root"}],"answer":["c"],"explanation":"SELinux autorise le serveur web à lire les fichiers étiquetés pour lui. Un dossier hors des emplacements habituels n’a pas ce type : on le déclare de façon persistante (semanage) et on l’applique (restorecon). Le journal d’audit (ausearch -m avc) confirme la cause.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"2e744441-c381-57e6-9c64-0a85953ae3d7","type":"multiple","prompt":"Cochez les mesures de durcissement SSH pertinentes pour des serveurs exposés.","choices":[{"id":"a","text":"Partager une même clé privée entre tous les administrateurs"},{"id":"b","text":"Autoriser les mots de passe vides pour les comptes de service"},{"id":"c","text":"Authentification par clé uniquement (PasswordAuthentication no)"},{"id":"d","text":"Interdire la connexion directe de root (PermitRootLogin no)"}],"answer":["c","d"],"explanation":"Les clés résistent aux attaques par mot de passe, et interdire root impose une connexion nominative puis une élévation tracée. Les mots de passe vides et les clés partagées effacent toute traçabilité et facilitent la compromission.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"afbe298f-847c-5669-bae6-8a23f2294680","type":"single","prompt":"À quoi sert auditd sur un serveur sensible ?","choices":[{"id":"a","text":"À chiffrer le disque"},{"id":"b","text":"À bloquer les intrusions réseau"},{"id":"c","text":"À mettre à jour le système automatiquement"},{"id":"d","text":"À journaliser, selon des règles, les accès à des fichiers critiques et des appels système, pour savoir qui a fait quoi"}],"answer":["d"],"explanation":"auditd enregistre par exemple chaque modification de /etc/sudoers ou chaque exécution par un compte donné. Il détecte et trace, il ne bloque pas ; ses journaux sont envoyés vers un système central pour résister à un effacement.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"49a84be0-cbe1-530a-a77b-5d1194c75b81","type":"single","prompt":"Une faille du noyau nécessite une mise à jour sur un serveur qui ne peut pas redémarrer avant la fenêtre de maintenance du mois prochain. Quelle approche est raisonnable ?","choices":[{"id":"a","text":"Désactiver le pare-feu pour faciliter la surveillance"},{"id":"b","text":"Appliquer un correctif à chaud (livepatch) si l’éditeur en fournit un, réduire l’exposition en attendant, et redémarrer à la fenêtre de maintenance"},{"id":"c","text":"Ne rien faire jusqu’au mois prochain"},{"id":"d","text":"Installer le nouveau noyau sans redémarrer et considérer le serveur corrigé"}],"answer":["b"],"explanation":"Un nouveau noyau installé n’est actif qu’après redémarrage : uname -r et needs-restarting (ou needrestart) le montrent. Le livepatch corrige la faille en mémoire en attendant. Ne rien faire laisse la faille ouverte un mois.","difficulty":"expert","platform":"linux"}$q$::jsonb),
    ($q${"id":"93f1fba2-373b-5131-a9ac-8f0749694636","type":"single","prompt":"Comment trouver quelle partie du code d’un processus consomme le CPU, sur un serveur en production, avec un impact limité ?","choices":[{"id":"a","text":"Échantillonner avec perf top ou perf record -p <pid>, qui mesure par prélèvements"},{"id":"b","text":"Augmenter la priorité du processus avec nice -20"},{"id":"c","text":"Redémarrer le processus en mode débogage"},{"id":"d","text":"Lancer strace -f sur le processus pendant une heure"}],"answer":["a"],"explanation":"perf échantillonne régulièrement la pile d’exécution avec un faible surcoût. strace intercepte chaque appel système et peut ralentir fortement le processus. Changer la priorité ne dit rien de la cause.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"e05e6521-e842-554a-bbe7-23ba429f0d76","type":"single","prompt":"Un serveur tombe à court de descripteurs de fichiers (« Too many open files ») pour un service. Comment relever la limite de ce service durablement ?","choices":[{"id":"a","text":"En redémarrant le serveur"},{"id":"b","text":"En supprimant des fichiers de /tmp"},{"id":"c","text":"Avec ulimit -n dans le terminal de l’administrateur"},{"id":"d","text":"Avec LimitNOFILE= dans son unité systemd (drop-in), puis redémarrer le service"}],"answer":["d"],"explanation":"Un service lancé par systemd ne lit pas les limites de la session de l’administrateur ni, en général, limits.conf : sa limite se règle dans l’unité. On vérifie aussi qu’il ne s’agit pas d’une fuite (descripteurs jamais fermés) avec ls /proc/<pid>/fd | wc -l dans le temps.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"085f3c77-2da6-54dc-b538-f6f7bf6fa968","type":"single","prompt":"Une application ouvre des milliers de connexions sortantes courtes et finit par échouer avec « Cannot assign requested address ». Quelle est la cause la plus probable ?","choices":[{"id":"a","text":"Un disque plein"},{"id":"b","text":"L’épuisement des ports source éphémères, occupés par des connexions en TIME_WAIT ; on réutilise les connexions (pool, keep-alive) et on vérifie la plage ip_local_port_range"},{"id":"c","text":"Un DNS lent"},{"id":"d","text":"Une carte réseau défectueuse"}],"answer":["b"],"explanation":"Chaque connexion sortante vers une même destination consomme un port source, qui reste réservé un moment en TIME_WAIT après fermeture. ss -s le montre. Réutiliser les connexions traite la cause ; élargir la plage de ports donne de la marge.","difficulty":"expert","platform":"linux"}$q$::jsonb),
    ($q${"id":"63ae0c31-c4a6-5940-920f-363646bbd16a","type":"single","prompt":"Qu’apporte journald avec `Storage=persistent` par rapport au réglage par défaut de certaines distributions ?","choices":[{"id":"a","text":"Les journaux survivent au redémarrage (dans /var/log/journal), ce qui permet d’analyser ce qui a précédé un plantage"},{"id":"b","text":"Les journaux ne prennent plus de place sur le disque"},{"id":"c","text":"Les journaux sont chiffrés"},{"id":"d","text":"Les journaux sont envoyés automatiquement vers un serveur central"}],"answer":["a"],"explanation":"En stockage volatil, le journal vit dans /run et disparaît au redémarrage, justement quand on en a besoin pour comprendre une panne. journalctl -b -1 lit alors le démarrage précédent. L’envoi vers un serveur central reste à configurer à part.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"2aa6f2d8-173d-5ec7-91e7-b323435e7cba","type":"single","prompt":"Que mesure un indicateur RPO (Recovery Point Objective) dans un plan de reprise ?","choices":[{"id":"a","text":"Le temps maximal pour remettre le service en route"},{"id":"b","text":"Le nombre de serveurs de secours"},{"id":"c","text":"Le coût de la sauvegarde"},{"id":"d","text":"La quantité maximale de données qu’on accepte de perdre, exprimée en temps depuis la dernière copie"}],"answer":["d"],"explanation":"Un RPO de 15 minutes impose une copie (sauvegarde, réplication, journaux) au moins toutes les 15 minutes. Le temps de remise en route est le RTO. Les deux se vérifient par des restaurations testées, pas seulement par des sauvegardes qui réussissent.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"6c1a2f17-0e79-540d-95b9-11359ab335cf","type":"multiple","prompt":"Vous préparez la migration d’un service critique vers un nouveau serveur. Cochez les éléments indispensables du plan.","choices":[{"id":"a","text":"Décommissionner l’ancien serveur avant la bascule pour éviter la confusion"},{"id":"b","text":"Une répétition de la bascule sur un environnement de test, avec la durée mesurée"},{"id":"c","text":"Prévenir les utilisateurs seulement en cas de problème"},{"id":"d","text":"Un critère de réussite mesurable et un plan de retour arrière testé, avec le moment où on le déclenche"}],"answer":["b","d"],"explanation":"On sait à l’avance quand la migration est réussie et quand on revient en arrière, et la répétition révèle les surprises et la durée réelle. Garder l’ancien serveur intact est justement ce qui rend le retour arrière possible ; la communication se fait avant.","difficulty":"expert","platform":"linux"}$q$::jsonb),
    ($q${"id":"acd7dda4-1638-5514-9484-b12b1ba205ba","type":"single","prompt":"Pourquoi préférer des minuteurs systemd (timers) à cron pour une tâche de maintenance ?","choices":[{"id":"a","text":"Ils ne nécessitent aucune configuration"},{"id":"b","text":"Ils journalisent chaque exécution dans journald, gèrent les exécutions manquées (Persistent=true) et profitent des limites et dépendances systemd"},{"id":"c","text":"cron est interdit sur les distributions récentes"},{"id":"d","text":"Ils s’exécutent plus vite"}],"answer":["b"],"explanation":"Avec un timer, systemctl list-timers montre la prochaine et la dernière exécution, journalctl -u leur sortie, et une exécution prévue pendant un arrêt est rattrapée au démarrage. cron reste disponible et fonctionne, mais sans ces garanties.","difficulty":"advanced","platform":"linux"}$q$::jsonb),
    ($q${"id":"0b0ca28c-9ea3-5cbf-ba57-202392587ea3","type":"single","prompt":"Un poste ping son passerelle 192.168.1.1 mais pas 8.8.8.8. Le DNS n’est pas encore en cause : pourquoi ?","choices":[{"id":"a","text":"Parce que le DNS ne sert que pour le réseau local"},{"id":"b","text":"Parce que le test vers 8.8.8.8 utilise une adresse IP : aucune résolution de nom n’intervient"},{"id":"c","text":"Parce que 8.8.8.8 est lui-même un serveur DNS"},{"id":"d","text":"Parce que ping n’utilise jamais le DNS"}],"answer":["b"],"explanation":"On teste couche par couche : une adresse IP ne passe pas par la résolution de noms, donc l’échec vient du routage, de la passerelle ou d’un filtrage. ping résout bien les noms quand on lui en donne un ; que 8.8.8.8 soit un serveur DNS ne change rien au test.","difficulty":"beginner","platform":"network"}$q$::jsonb),
    ($q${"id":"386b3a43-bd78-5425-b54a-14d8dbc15744","type":"single","prompt":"Que montre la commande `ip route` sur un serveur Linux qui n’a pas de ligne `default via …` ?","choices":[{"id":"a","text":"Que le pare-feu bloque tout le trafic sortant"},{"id":"b","text":"Que la carte réseau est désactivée"},{"id":"c","text":"Que le DNS est mal configuré"},{"id":"d","text":"Que le serveur sait joindre ses réseaux directement connectés, mais pas Internet"}],"answer":["d"],"explanation":"Sans route par défaut, le noyau ne sait pas où envoyer un paquet destiné à un réseau qu’il ne connaît pas. Les réseaux locaux, eux, restent joignables. Une carte désactivée ferait disparaître aussi ses routes locales ; le DNS et le pare-feu sont d’autres sujets.","difficulty":"beginner","platform":"network"}$q$::jsonb),
    ($q${"id":"c34b2b0d-4838-53f4-83f8-3222d6589294","type":"single","prompt":"Combien d’adresses utilisables pour des hôtes offre un réseau en /26 ?","choices":[{"id":"a","text":"30"},{"id":"b","text":"62"},{"id":"c","text":"64"},{"id":"d","text":"126"}],"answer":["b"],"explanation":"Un /26 laisse 32 − 26 = 6 bits pour les hôtes, soit 2⁶ = 64 adresses. On retire l’adresse du réseau et celle de diffusion : 62 utilisables. 30 correspond à un /27 et 126 à un /25.","difficulty":"beginner","platform":"network"}$q$::jsonb),
    ($q${"id":"b2605794-1425-5371-a1b6-8fd3a7906ddd","type":"single","prompt":"Deux postes en 10.0.0.10/24 et 10.0.1.20/24 sont branchés sur le même commutateur, sans routeur. Peuvent-ils communiquer ?","choices":[{"id":"a","text":"Oui, car ils sont sur le même commutateur"},{"id":"b","text":"Oui, car les deux adresses commencent par 10.0"},{"id":"c","text":"Non : avec ce masque, ils sont dans deux réseaux différents et chacun cherche une passerelle pour joindre l’autre"},{"id":"d","text":"Non, car 10.0.0.0 est une plage publique"}],"answer":["c"],"explanation":"Le masque /24 place le premier poste dans 10.0.0.0/24 et le second dans 10.0.1.0/24. Chaque poste n’envoie en direct (ARP) qu’aux hôtes de son propre réseau ; pour l’autre il faut un routeur. 10.0.0.0/8 est une plage privée.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"f8dbae0f-c3e1-5448-bb1d-f56bc0cfc953","type":"single","prompt":"Un poste obtient l’adresse 169.254.37.12. Qu’est-ce que cela indique ?","choices":[{"id":"a","text":"Que le serveur DNS est injoignable"},{"id":"b","text":"Qu’il n’a reçu aucune réponse d’un serveur DHCP et s’est attribué une adresse locale automatique"},{"id":"c","text":"Que son adresse est en conflit avec un autre poste"},{"id":"d","text":"Qu’il a reçu une adresse publique de son fournisseur"}],"answer":["b"],"explanation":"169.254.0.0/16 est la plage APIPA (link-local) : le système se l’attribue quand le DHCP ne répond pas. On vérifie le câble ou le Wi-Fi, le VLAN du port et le serveur DHCP. Ce n’est ni une adresse publique ni un symptôme DNS.","difficulty":"beginner","platform":"network"}$q$::jsonb),
    ($q${"id":"4f993012-9338-56f8-9380-06af128930d4","type":"single","prompt":"Dans quel ordre se déroule un échange DHCP classique ?","choices":[{"id":"a","text":"DISCOVER, REQUEST, OFFER, ACK"},{"id":"b","text":"REQUEST, OFFER, DISCOVER, ACK"},{"id":"c","text":"DISCOVER, OFFER, REQUEST, ACK"},{"id":"d","text":"OFFER, DISCOVER, ACK, REQUEST"}],"answer":["c"],"explanation":"Le client cherche un serveur (DISCOVER, en diffusion), un serveur propose une adresse (OFFER), le client la demande formellement (REQUEST) et le serveur confirme le bail (ACK). On retient « DORA ».","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"c21c0450-b111-5643-9b44-05d56bc48a00","type":"single","prompt":"`dig intranet.exemple.lan` répond NXDOMAIN, mais `dig @10.0.0.53 intranet.exemple.lan` renvoie la bonne adresse. Que faut-il corriger ?","choices":[{"id":"a","text":"Le cache du navigateur"},{"id":"b","text":"Le résolveur utilisé par défaut par le poste, qui n’est pas le serveur DNS interne"},{"id":"c","text":"L’enregistrement A de intranet.exemple.lan sur 10.0.0.53"},{"id":"d","text":"La route par défaut du poste"}],"answer":["b"],"explanation":"Interrogé directement, le serveur interne connaît le nom : l’enregistrement est bon. C’est le résolveur configuré par défaut (resolv.conf, netplan, DHCP) qui pointe vers un serveur public, lequel ne connaît pas la zone interne. Le routage fonctionne puisque 10.0.0.53 répond.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"9c73cfd9-cedc-5514-9c72-d4d43c236af2","type":"single","prompt":"Vous changez l’adresse IP d’un serveur web, mais certains clients continuent d’aller sur l’ancienne pendant des heures. Quelle en est la cause la plus probable ?","choices":[{"id":"a","text":"Le TTL de l’ancien enregistrement DNS, que les résolveurs gardent en cache jusqu’à son expiration"},{"id":"b","text":"Le bail DHCP des clients"},{"id":"c","text":"Le MTU du réseau"},{"id":"d","text":"La table ARP du serveur"}],"answer":["a"],"explanation":"Les résolveurs conservent une réponse DNS pendant son TTL. On abaisse le TTL quelques jours avant une migration, puis on le remonte après. Le DHCP des clients, la table ARP ou le MTU n’influencent pas l’adresse obtenue pour un nom.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"94afd2f7-13a5-5a19-aae9-f9721cced4c2","type":"single","prompt":"Quel type d’enregistrement DNS désigne les serveurs de messagerie d’un domaine ?","choices":[{"id":"a","text":"CNAME"},{"id":"b","text":"PTR"},{"id":"c","text":"AAAA"},{"id":"d","text":"MX"}],"answer":["d"],"explanation":"MX (Mail eXchanger) indique où livrer le courrier d’un domaine, avec une priorité. CNAME crée un alias, PTR sert à la résolution inverse (IP vers nom) et AAAA donne une adresse IPv6.","difficulty":"beginner","platform":"network"}$q$::jsonb),
    ($q${"id":"11094186-ffa2-5204-9efa-66eeb0f2cc56","type":"multiple","prompt":"Cochez toutes les affirmations justes sur TCP et UDP.","choices":[{"id":"a","text":"UDP n’établit pas de connexion et ne garantit ni l’ordre ni la livraison"},{"id":"b","text":"DNS utilise uniquement TCP"},{"id":"c","text":"UDP est toujours plus sûr que TCP"},{"id":"d","text":"TCP établit une connexion (poignée de main) et retransmet les segments perdus"}],"answer":["a","d"],"explanation":"TCP est orienté connexion et fiable ; UDP est sans connexion et laisse la fiabilité à l’application. DNS utilise UDP pour la plupart des requêtes et TCP pour les grandes réponses et les transferts de zone. La sécurité ne dépend pas du choix TCP ou UDP.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"99017441-76a3-589f-a5cc-c17e2ad76963","type":"single","prompt":"`traceroute` vers un site distant s’arrête après le troisième saut, avec des étoiles ensuite, alors que le site s’affiche normalement dans le navigateur. Que conclure ?","choices":[{"id":"a","text":"Le réseau est coupé après le troisième routeur"},{"id":"b","text":"Le DNS du site est faux"},{"id":"c","text":"Le site est en panne"},{"id":"d","text":"Rien d’alarmant : des équipements peuvent ne pas répondre aux sondes de traceroute tout en relayant le trafic"}],"answer":["d"],"explanation":"Beaucoup de routeurs et de pare-feu filtrent ou limitent les réponses ICMP « TTL dépassé ». Si le service répond, le chemin fonctionne. Des étoiles ne prouvent une coupure que lorsque le service lui-même est injoignable.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"023c81c1-749d-540c-9e85-d98e0b88e809","type":"single","prompt":"Les pages web légères s’affichent, mais les gros téléchargements et certaines pages HTTPS restent bloqués à travers un tunnel VPN. Quelle cause rechercher ?","choices":[{"id":"a","text":"Un enregistrement DNS manquant"},{"id":"b","text":"Un problème de MTU : les paquets trop grands sont perdus et l’ICMP « fragmentation nécessaire » est filtré"},{"id":"c","text":"Un bail DHCP expiré"},{"id":"d","text":"Une mauvaise adresse de passerelle"}],"answer":["b"],"explanation":"Le tunnel ajoute des en-têtes et réduit la taille utile des paquets. Si l’ICMP de découverte du MTU est bloqué, les petits échanges passent et les gros paquets disparaissent. On le vérifie avec ping -M do -s <taille>, puis on ajuste le MTU ou le MSS. Une passerelle fausse ou un DNS manquant casseraient tout, pas seulement les gros transferts.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"e15eacaa-7ef9-5ba2-8d71-3c26e60c9ac5","type":"single","prompt":"À quoi sert un VLAN ?","choices":[{"id":"a","text":"À accélérer le débit d’un lien"},{"id":"b","text":"À séparer logiquement des réseaux sur les mêmes commutateurs, chacun avec son propre domaine de diffusion"},{"id":"c","text":"À chiffrer le trafic entre deux sites"},{"id":"d","text":"À attribuer automatiquement les adresses IP"}],"answer":["b"],"explanation":"Un VLAN découpe un commutateur en plusieurs réseaux de niveau 2 isolés : la diffusion d’un VLAN n’atteint pas les autres, et il faut un routeur pour passer de l’un à l’autre. Le chiffrement relève d’un VPN et l’adressage du DHCP.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"53e6aa95-acb5-5ed1-8b58-445eebb5e47b","type":"single","prompt":"Un port de commutateur relié à un autre commutateur doit transporter les VLAN 10, 20 et 30. Comment le configurer ?","choices":[{"id":"a","text":"En port d’accès dans les trois VLAN à la fois"},{"id":"b","text":"En port trunk (802.1Q) autorisant ces trois VLAN"},{"id":"c","text":"Désactiver les VLAN sur ce port"},{"id":"d","text":"En port d’accès dans le VLAN 10"}],"answer":["b"],"explanation":"Un port d’accès n’appartient qu’à un seul VLAN et envoie des trames sans étiquette. Pour transporter plusieurs VLAN entre deux commutateurs, on utilise un trunk 802.1Q, qui étiquette chaque trame avec son VLAN. On limite la liste aux VLAN nécessaires.","difficulty":"advanced","platform":"network"}$q$::jsonb),
    ($q${"id":"d94853eb-0798-56ee-baca-aa75913e536f","type":"single","prompt":"Que fait le NAT (masquerade) d’une box ou d’un routeur d’entreprise vers Internet ?","choices":[{"id":"a","text":"Il chiffre le trafic sortant"},{"id":"b","text":"Il remplace l’adresse source privée des postes par l’adresse publique du routeur et mémorise la correspondance pour les réponses"},{"id":"c","text":"Il bloque tout le trafic entrant par conception de sécurité"},{"id":"d","text":"Il attribue les adresses privées aux postes"}],"answer":["b"],"explanation":"Le NAT réécrit l’adresse (et souvent le port) source et garde une table de traduction pour renvoyer les réponses au bon poste. Il ne chiffre rien et n’attribue pas les adresses (c’est le DHCP). Il ne remplace pas un pare-feu, même s’il rend les postes non joignables directement.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"080c8b41-6e75-5094-bd5a-01320a01288d","type":"single","prompt":"Une application est injoignable depuis l’extérieur sur le port 8443. Sur le serveur, `ss -tlnp` montre `127.0.0.1:8443`. Quelle est la cause ?","choices":[{"id":"a","text":"Le service n’écoute que sur l’interface locale : il faut le configurer pour écouter sur l’adresse du réseau (ou 0.0.0.0)"},{"id":"b","text":"Le service n’est pas démarré"},{"id":"c","text":"La route par défaut est absente"},{"id":"d","text":"Le port 8443 est réservé au système"}],"answer":["a"],"explanation":"L’adresse 127.0.0.1 n’est joignable que depuis la machine elle-même. Le service tourne bien (il apparaît dans ss) et le port n’a rien de réservé. Après correction de l’adresse d’écoute, on vérifie aussi le pare-feu.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"ff78dace-1ba0-5c73-9797-0ca97a3bf63d","type":"multiple","prompt":"Vous ajoutez une règle de pare-feu pour ouvrir le port 443 sur un serveur distant administré en SSH. Cochez les précautions utiles.","choices":[{"id":"a","text":"Désactiver le pare-feu le temps du test"},{"id":"b","text":"Prévoir un retour arrière automatique ou un accès console en cas d’erreur"},{"id":"c","text":"Ouvrir tous les ports puis refermer ceux qui ne servent pas"},{"id":"d","text":"Vérifier que la règle autorisant SSH reste présente avant d’appliquer une politique par défaut en refus"}],"answer":["b","d"],"explanation":"La principale erreur est de se couper soi-même l’accès SSH : on garde la règle SSH et un moyen de revenir en arrière (console, minuterie de restauration). Désactiver le pare-feu ou tout ouvrir expose le serveur pendant la manipulation.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"94544775-2cc0-57f8-97fe-fe73c42f9a31","type":"single","prompt":"Quelle commande montre les ports TCP en écoute et le processus associé sur un serveur Linux ?","choices":[{"id":"a","text":"arp -a"},{"id":"b","text":"ss -tlnp"},{"id":"c","text":"ip addr"},{"id":"d","text":"dig"}],"answer":["b"],"explanation":"ss -tlnp liste les sockets TCP (t) en écoute (l), en numérique (n), avec le processus (p, nécessite les droits root pour les autres comptes). ip addr montre les adresses, dig interroge le DNS et arp -a la table ARP.","difficulty":"beginner","platform":"network"}$q$::jsonb),
    ($q${"id":"fc0b09e4-2ef3-533f-b18f-b4752b1a7496","type":"single","prompt":"Deux machines du même réseau se disputent la même adresse IP. Quel symptôme est typique ?","choices":[{"id":"a","text":"Une connexion qui marche puis se coupe par intermittence, selon la machine qui a répondu en dernier à l’ARP"},{"id":"b","text":"Une erreur NXDOMAIN"},{"id":"c","text":"Une absence totale de route par défaut"},{"id":"d","text":"Un MTU réduit"}],"answer":["a"],"explanation":"Les deux machines répondent aux requêtes ARP pour la même IP ; les autres postes mettent à jour leur table au gré des réponses et le trafic bascule de l’une à l’autre. arping -D ou la table ARP du routeur aident à trouver les deux adresses MAC en cause.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"9835809b-c1c6-50b3-952f-1149d3f4ffab","type":"single","prompt":"Avec tcpdump, vous voyez des SYN partir vers un serveur sans aucune réponse, ni SYN-ACK ni RST. Que pouvez-vous en déduire ?","choices":[{"id":"a","text":"La connexion est établie"},{"id":"b","text":"Le paquet est probablement filtré en silence (pare-feu) ou perdu en route, plutôt que refusé par un port fermé"},{"id":"c","text":"Le service écoute mais refuse la connexion"},{"id":"d","text":"Le nom DNS ne se résout pas"}],"answer":["b"],"explanation":"Un port fermé sur un hôte joignable répond par un RST (« connexion refusée »). L’absence de toute réponse évoque un filtrage qui jette les paquets ou un problème de routage. Le DNS est déjà résolu puisque les SYN partent vers une adresse.","difficulty":"advanced","platform":"network"}$q$::jsonb),
    ($q${"id":"f0374032-5571-5d75-9a61-4fc341012c96","type":"single","prompt":"Qu’est-ce qui distingue un VPN site à site d’un VPN d’accès distant ?","choices":[{"id":"a","text":"L’accès distant ne fonctionne qu’en IPv6"},{"id":"b","text":"Le site à site n’est pas chiffré"},{"id":"c","text":"Le site à site relie deux réseaux entiers de façon permanente ; l’accès distant connecte un poste isolé au réseau de l’entreprise"},{"id":"d","text":"Il n’y a aucune différence"}],"answer":["c"],"explanation":"Un VPN site à site s’établit entre deux passerelles et route le trafic de deux réseaux. Un VPN d’accès distant relie un utilisateur nomade. Les deux sont chiffrés et fonctionnent en IPv4 comme en IPv6.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"9491bf6a-a569-5bbd-bb5f-0d4aee3dd2a8","type":"single","prompt":"Quel est l’équivalent IPv6 de 127.0.0.1 ?","choices":[{"id":"a","text":"::"},{"id":"b","text":"ff02::1"},{"id":"c","text":"::1"},{"id":"d","text":"fe80::1"}],"answer":["c"],"explanation":"::1 est l’adresse de bouclage IPv6. fe80::/10 est la plage link-local, :: l’adresse non spécifiée et ff02::1 l’adresse multicast de tous les nœuds du lien.","difficulty":"intermediate","platform":"network"}$q$::jsonb),
    ($q${"id":"87623db7-1334-5167-ba00-e5cfdc538e9b","type":"single","prompt":"Un poste a deux routes : `10.0.0.0/8 via 10.1.1.1` et `10.20.0.0/16 via 10.1.1.254`. Par où part un paquet vers 10.20.5.7 ?","choices":[{"id":"a","text":"Par 10.1.1.254, car la route la plus précise (préfixe le plus long) l’emporte"},{"id":"b","text":"Par la route par défaut"},{"id":"c","text":"Par 10.1.1.1, car la route a été ajoutée en premier"},{"id":"d","text":"Par les deux, en alternance"}],"answer":["a"],"explanation":"Le noyau choisit la route dont le préfixe correspond le plus longuement à la destination : /16 est plus précis que /8. L’ordre d’ajout ne compte pas, et la route par défaut (/0) ne sert que si aucune autre ne correspond.","difficulty":"advanced","platform":"network"}$q$::jsonb),
    ($q${"id":"db1c5959-7134-572f-90a9-60c93ac234ed","type":"multiple","prompt":"Un utilisateur dit « Internet ne marche pas ». Cochez les vérifications qui apportent une information avant toute modification.","choices":[{"id":"a","text":"Réinitialiser immédiatement le routeur de l’étage"},{"id":"b","text":"Tester un ping vers la passerelle, puis vers une adresse IP publique, puis vers un nom"},{"id":"c","text":"Regarder l’adresse IP, le masque et la passerelle obtenus par le poste"},{"id":"d","text":"Changer le serveur DNS du poste au hasard"}],"answer":["b","c"],"explanation":"On remonte les couches : configuration du poste, accès à la passerelle, sortie vers Internet par adresse IP, puis résolution de noms. Chaque étape situe la panne. Redémarrer un équipement partagé ou changer des réglages au hasard efface les indices et peut gêner d’autres utilisateurs.","difficulty":"beginner","platform":"network"}$q$::jsonb),
    ($q${"id":"41a0e2f8-0bee-5930-b833-8f15e9c8ad69","type":"single","prompt":"Quelle est la différence entre une image et un conteneur Docker ?","choices":[{"id":"a","text":"L’image contient le noyau Linux, le conteneur non"},{"id":"b","text":"Ce sont deux noms pour la même chose"},{"id":"c","text":"L’image est un modèle en lecture seule ; le conteneur est une instance en cours d’exécution de cette image, avec sa propre couche inscriptible"},{"id":"d","text":"Le conteneur est un fichier compressé que l’on télécharge, l’image est le processus qui tourne"}],"answer":["c"],"explanation":"On construit ou télécharge une image, puis on lance un ou plusieurs conteneurs à partir d’elle. Chaque conteneur ajoute une couche inscriptible au-dessus des couches de l’image. Ni l’image ni le conteneur n’embarquent de noyau : ils partagent celui de l’hôte.","difficulty":"beginner","platform":"docker"}$q$::jsonb),
    ($q${"id":"d508aff6-cf4e-5518-816c-2aca0f72a9f7","type":"single","prompt":"Un conteneur s’arrête aussitôt démarré. Quelle commande donne en premier la raison ?","choices":[{"id":"a","text":"docker logs <conteneur>"},{"id":"b","text":"docker rm <conteneur>"},{"id":"c","text":"docker pull <image>"},{"id":"d","text":"docker network ls"}],"answer":["a"],"explanation":"docker logs affiche ce que le processus principal a écrit avant de s’arrêter, souvent l’erreur elle-même. docker ps -a donne aussi le code de sortie. Supprimer le conteneur efface ces indices ; retélécharger l’image ou lister les réseaux ne dit rien de la cause.","difficulty":"beginner","platform":"docker"}$q$::jsonb),
    ($q${"id":"992a6233-32ac-5a50-b43f-8a7c3bcc9537","type":"single","prompt":"`docker compose up` échoue avec « Bind for 0.0.0.0:5432 failed: port is already allocated ». Que vérifier d’abord ?","choices":[{"id":"a","text":"La connexion Internet de l’hôte"},{"id":"b","text":"Le contenu du volume de données"},{"id":"c","text":"La version de l’image PostgreSQL"},{"id":"d","text":"Quel processus ou quel autre conteneur utilise déjà le port 5432 sur l’hôte (ss -tlnp, docker ps)"}],"answer":["d"],"explanation":"Le message concerne le port publié sur l’hôte : un PostgreSQL installé localement ou un autre conteneur l’occupe déjà. On l’identifie avant de choisir : arrêter l’autre service ou publier sur un autre port de l’hôte (« 5433:5432 »). L’image et le volume ne sont pas en cause.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"08a52067-24b9-5a50-8eee-b95cac8b2052","type":"single","prompt":"Dans `ports: - \"8080:80\"`, que signifient les deux nombres ?","choices":[{"id":"a","text":"8080 est le port du conteneur, 80 celui de l’hôte"},{"id":"b","text":"L’application écoute sur les deux ports"},{"id":"c","text":"Docker choisit au hasard entre 8080 et 80"},{"id":"d","text":"8080 est le port de l’hôte, 80 le port sur lequel l’application écoute dans le conteneur"}],"answer":["d"],"explanation":"La syntaxe est HÔTE:CONTENEUR. Les clients se connectent à l’hôte sur 8080, et Docker transmet au port 80 du conteneur. L’application n’a pas besoin de savoir que le port 8080 existe.","difficulty":"beginner","platform":"docker"}$q$::jsonb),
    ($q${"id":"9adbf431-55da-5255-ad6c-267ee2ab5256","type":"single","prompt":"Après une mise à jour de l’image, un conteneur redémarre en boucle et ses logs indiquent « DATABASE_URL is required ». Le fichier compose définit `DB_URL`. Quelle est la démarche la plus sûre ?","choices":[{"id":"a","text":"Revenir à l’image latest sans regarder"},{"id":"b","text":"Ajouter restart: always pour qu’il finisse par démarrer"},{"id":"c","text":"Supprimer le volume de la base pour repartir de zéro"},{"id":"d","text":"Lire les notes de version de l’image, constater le renommage de la variable et adapter la configuration en conséquence"}],"answer":["d"],"explanation":"Le message dit exactement ce qui manque : la nouvelle version attend un autre nom de variable. On vérifie dans les notes de version, on corrige, puis on redéploie. Supprimer le volume détruit des données sans rapport avec l’erreur ; un redémarrage automatique ne corrige pas une configuration fausse.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"9aa9b904-fcff-567f-8cae-33d8646726ca","type":"single","prompt":"Que devient une donnée écrite dans un conteneur, hors de tout volume, lorsqu’on supprime puis recrée ce conteneur ?","choices":[{"id":"a","text":"Elle est conservée tant que l’hôte n’a pas redémarré"},{"id":"b","text":"Elle est conservée dans /var/lib/docker/backup"},{"id":"c","text":"Elle est copiée automatiquement dans l’image"},{"id":"d","text":"Elle est perdue : la couche inscriptible disparaît avec le conteneur"}],"answer":["d"],"explanation":"La couche inscriptible appartient au conteneur et disparaît avec docker rm. Les données à conserver (base de données, fichiers envoyés) vont dans un volume ou un montage. Docker ne sauvegarde rien et ne modifie jamais l’image.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"ca902f07-2a48-5169-82fb-d074232a501b","type":"multiple","prompt":"Cochez les affirmations justes sur les volumes nommés et les montages de répertoire (bind mounts).","choices":[{"id":"a","text":"Un bind mount expose un chemin précis de l’hôte dans le conteneur"},{"id":"b","text":"docker compose down supprime toujours les volumes nommés"},{"id":"c","text":"Un bind mount copie le répertoire une fois au démarrage, puis les deux évoluent séparément"},{"id":"d","text":"Un volume nommé est géré par Docker et survit à la suppression du conteneur"}],"answer":["a","d"],"explanation":"Les volumes nommés vivent indépendamment des conteneurs ; down ne les supprime qu’avec l’option -v, à manier avec prudence. Un bind mount est un accès direct au répertoire de l’hôte : les modifications sont visibles des deux côtés immédiatement, sans copie.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"5110ffc6-1da0-5b3c-948d-935fab8b3b2b","type":"single","prompt":"Dans un fichier compose, le service `api` doit joindre la base du service `db`. Quelle adresse utiliser ?","choices":[{"id":"a","text":"Le nom du service, db : le DNS interne de Docker le résout sur le réseau du projet"},{"id":"b","text":"L’adresse IP du conteneur db relevée avec docker inspect"},{"id":"c","text":"L’adresse publique de l’hôte"},{"id":"d","text":"localhost, car tous les conteneurs partagent la même pile réseau"}],"answer":["a"],"explanation":"Chaque conteneur a sa propre pile réseau : localhost désigne le conteneur api lui-même. Compose crée un réseau où les services se joignent par leur nom. Une adresse IP de conteneur change à chaque recréation, et passer par l’adresse publique impose de publier la base inutilement.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"cd74a146-d695-576c-9237-3686a00c7078","type":"single","prompt":"Pourquoi place-t-on `COPY package.json` et l’installation des dépendances avant `COPY . .` dans un Dockerfile ?","choices":[{"id":"a","text":"Parce que Docker refuse de copier le code avant les dépendances"},{"id":"b","text":"Pour réduire la sécurité de l’image"},{"id":"c","text":"Parce que COPY . . ne copie pas package.json"},{"id":"d","text":"Pour profiter du cache des couches : tant que les dépendances ne changent pas, l’étape d’installation n’est pas rejouée"}],"answer":["d"],"explanation":"Chaque instruction produit une couche mise en cache ; une couche est reconstruite dès que ses entrées changent, ainsi que toutes les suivantes. En copiant d’abord le manifeste, une modification du code ne relance pas l’installation des dépendances.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"3d60dc1c-0c57-5ba9-8cfc-ed9e06baa005","type":"single","prompt":"Quel est l’intérêt d’un build multi-étapes (multi-stage) ?","choices":[{"id":"a","text":"Lancer plusieurs conteneurs à partir d’un seul Dockerfile"},{"id":"b","text":"Construire l’image sur plusieurs machines à la fois"},{"id":"c","text":"Chiffrer les couches de l’image"},{"id":"d","text":"Compiler dans une première image complète, puis ne copier que le résultat dans une image finale légère, sans outils de compilation"}],"answer":["d"],"explanation":"L’image finale ne contient que ce qu’il faut pour exécuter : elle est plus petite, plus rapide à déployer et expose moins de logiciels vulnérables. Compilateurs, sources et caches restent dans l’étape intermédiaire.","difficulty":"advanced","platform":"docker"}$q$::jsonb),
    ($q${"id":"36dab4ba-4557-592b-ae91-c3b533952acd","type":"single","prompt":"Pourquoi éviter `image: monapp:latest` en production ?","choices":[{"id":"a","text":"latest désactive les mises à jour de sécurité"},{"id":"b","text":"latest ne désigne pas une version précise : deux déploiements peuvent tirer des images différentes et un retour arrière devient incertain"},{"id":"c","text":"latest est toujours plus ancienne que les autres étiquettes"},{"id":"d","text":"Docker interdit latest en production"}],"answer":["b"],"explanation":"latest est une étiquette mobile, pas une garantie de nouveauté ni de stabilité. On fige une version (monapp:2.4.1, voire le condensat sha256) pour savoir exactement ce qui tourne et pouvoir revenir à la version précédente.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"d569142f-1c58-5cab-b5fc-6c78e3785833","type":"single","prompt":"Un mot de passe a été passé avec `ENV DB_PASSWORD=…` dans le Dockerfile, puis l’instruction a été supprimée dans une version suivante. Le secret est-il en sécurité ?","choices":[{"id":"a","text":"Oui, si l’image est privée"},{"id":"b","text":"Non : il reste visible dans les anciennes images et dans l’historique de leurs couches (docker history, docker inspect) ; il faut le changer"},{"id":"c","text":"Oui, puisque l’instruction a été retirée"},{"id":"d","text":"Oui, car les variables ENV sont chiffrées"}],"answer":["b"],"explanation":"Les instructions et variables d’une image sont lisibles par quiconque y a accès, et toutes les images déjà poussées le gardent. On considère le secret comme exposé et on le renouvelle ; ensuite, on le fournit au lancement (secret, variable d’environnement au déploiement, gestionnaire de secrets).","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"b2acc44a-b1cf-57e1-81e9-59c237bf8164","type":"multiple","prompt":"Cochez les mesures qui réduisent les risques d’un conteneur en production.","choices":[{"id":"a","text":"Faire tourner le processus avec un utilisateur non root (instruction USER)"},{"id":"b","text":"Lancer le conteneur avec --privileged pour éviter les erreurs de droits"},{"id":"c","text":"Monter /var/run/docker.sock dans le conteneur applicatif"},{"id":"d","text":"Ne publier que les ports nécessaires"}],"answer":["a","d"],"explanation":"Un processus non root et une surface réseau minimale limitent l’impact d’une compromission. --privileged et le montage du socket Docker donnent au conteneur un contrôle quasi total de l’hôte : à réserver aux rares outils qui en ont réellement besoin.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"2a24a5ff-509c-5cba-86a6-ad1a4591b0a2","type":"single","prompt":"Que fait `restart: unless-stopped` ?","choices":[{"id":"a","text":"Le conteneur ne redémarre jamais"},{"id":"b","text":"Docker corrige l’erreur qui a provoqué l’arrêt"},{"id":"c","text":"Docker redémarre le conteneur s’il s’arrête ou au redémarrage du démon, sauf s’il a été arrêté volontairement"},{"id":"d","text":"Le conteneur redémarre seulement en cas de mise à jour de l’image"}],"answer":["c"],"explanation":"Cette politique relance le conteneur après un arrêt inattendu ou un redémarrage de l’hôte, mais respecte un docker stop manuel. Elle ne corrige rien : un conteneur mal configuré redémarrera en boucle, d’où l’importance de lire ses logs.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"ab5f836c-4fe6-5d4e-83bb-a059e49a66a5","type":"single","prompt":"Que vérifie un HEALTHCHECK ajouté à une image ?","choices":[{"id":"a","text":"Que le conteneur tourne avec un utilisateur non root"},{"id":"b","text":"Que l’hôte a assez d’espace disque"},{"id":"c","text":"Que l’application répond réellement (par exemple une URL de santé), pas seulement que le processus existe"},{"id":"d","text":"Que l’image n’a pas de vulnérabilité connue"}],"answer":["c"],"explanation":"Un processus peut tourner tout en étant bloqué. Le HEALTHCHECK exécute régulièrement une commande et marque le conteneur healthy ou unhealthy, ce que compose (depends_on: condition: service_healthy) et les orchestrateurs utilisent. Il ne fait pas d’analyse de vulnérabilités.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"40019e49-56c1-5716-861b-da99647477a7","type":"single","prompt":"`depends_on: [db]` est présent, pourtant l’API échoue au démarrage car la base n’accepte pas encore de connexions. Pourquoi ?","choices":[{"id":"a","text":"depends_on est ignoré par compose"},{"id":"b","text":"La base doit être déclarée après l’API dans le fichier"},{"id":"c","text":"Sans condition, depends_on n’attend que le démarrage du conteneur db, pas que PostgreSQL soit prêt"},{"id":"d","text":"L’API et la base ne sont pas sur le même réseau"}],"answer":["c"],"explanation":"Par défaut, compose lance db avant api mais n’attend pas que le service soit opérationnel. On ajoute un healthcheck à db et condition: service_healthy, et l’application doit de toute façon savoir réessayer sa connexion. L’ordre dans le fichier n’a pas d’effet.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"02bae941-dff0-5961-89ad-79ad2db0acad","type":"single","prompt":"Comment ouvrir un shell dans un conteneur qui tourne, pour inspecter sa configuration ?","choices":[{"id":"a","text":"docker run -it <image> sh"},{"id":"b","text":"docker exec -it <conteneur> sh"},{"id":"c","text":"docker attach <image>"},{"id":"d","text":"docker build -t shell ."}],"answer":["b"],"explanation":"docker exec lance une nouvelle commande dans le conteneur existant. docker run créerait un nouveau conteneur, qui n’a pas l’état du premier ; docker attach se branche sur le processus principal, et build construit une image.","difficulty":"beginner","platform":"docker"}$q$::jsonb),
    ($q${"id":"c81ef6f4-8478-5ef5-a968-5f987febedae","type":"single","prompt":"Le disque de l’hôte se remplit et `docker system df` montre beaucoup d’images et de conteneurs arrêtés. Quelle démarche est raisonnable ?","choices":[{"id":"a","text":"Lire ce que docker system prune supprimerait, vérifier qu’aucune donnée utile n’est concernée, puis nettoyer (sans -a --volumes à l’aveugle)"},{"id":"b","text":"Supprimer /var/lib/docker à la main"},{"id":"c","text":"Redémarrer le démon Docker"},{"id":"d","text":"Lancer docker system prune -a --volumes sans regarder"}],"answer":["a"],"explanation":"prune supprime les conteneurs arrêtés, les réseaux inutilisés et les images orphelines ; avec --volumes il efface aussi les volumes non utilisés, qui peuvent contenir des données. On regarde d’abord, on nettoie ensuite. Supprimer /var/lib/docker à la main casse l’installation.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"a56a4109-c201-55ea-a497-ead352a4f722","type":"single","prompt":"Un conteneur est tué avec le code de sortie 137. Que cela suggère-t-il en premier ?","choices":[{"id":"a","text":"Le port est déjà utilisé"},{"id":"b","text":"L’image est introuvable"},{"id":"c","text":"L’application s’est terminée normalement"},{"id":"d","text":"Le processus a reçu SIGKILL, souvent parce qu’il a dépassé sa limite de mémoire (OOMKilled dans docker inspect)"}],"answer":["d"],"explanation":"137 = 128 + 9 : le processus a été tué par le signal 9. docker inspect indique State.OOMKilled si la limite mémoire est en cause. Une fin normale renvoie 0 ; un port occupé ou une image absente empêchent le démarrage avec un message explicite.","difficulty":"advanced","platform":"docker"}$q$::jsonb),
    ($q${"id":"8943c14b-a276-5027-a659-06bdbd8a1819","type":"single","prompt":"Pourquoi ajouter un fichier `.dockerignore` ?","choices":[{"id":"a","text":"Pour ne pas envoyer au build les fichiers inutiles ou sensibles (.git, node_modules, .env), ce qui accélère le build et évite de les embarquer dans l’image"},{"id":"b","text":"Pour empêcher Docker de lire les variables d’environnement"},{"id":"c","text":"Pour cacher le Dockerfile aux autres utilisateurs"},{"id":"d","text":"Pour ignorer les erreurs de build"}],"answer":["a"],"explanation":"Le contexte de build est envoyé en entier au moteur : un .env ou un dépôt .git copiés par COPY . . se retrouveraient dans l’image. .dockerignore réduit ce contexte, accélère le build et évite les fuites.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"d5e8150e-27b9-5833-a23c-f8a2bae0ba55","type":"single","prompt":"Quelle différence entre `ENTRYPOINT` et `CMD` ?","choices":[{"id":"a","text":"CMD s’exécute au build, ENTRYPOINT au démarrage"},{"id":"b","text":"ENTRYPOINT fixe l’exécutable du conteneur ; CMD fournit des arguments par défaut, remplacés par ceux donnés à docker run"},{"id":"c","text":"ENTRYPOINT n’est utilisé que sous Windows"},{"id":"d","text":"Ce sont deux synonymes"}],"answer":["b"],"explanation":"Avec ENTRYPOINT [\"nginx\"] et CMD [\"-g\", \"daemon off;\"], docker run image -t remplace seulement les arguments. Les deux s’appliquent au démarrage du conteneur ; c’est RUN qui s’exécute au build.","difficulty":"advanced","platform":"docker"}$q$::jsonb),
    ($q${"id":"2da6ed46-09b1-5d21-85d6-0e683251b54b","type":"single","prompt":"Vous publiez une base de données avec `ports: - \"5432:5432\"` sur un serveur exposé à Internet. Quel est le risque ?","choices":[{"id":"a","text":"La base devient joignable depuis Internet, y compris quand le pare-feu de l’hôte paraît fermé, car Docker ajoute ses propres règles"},{"id":"b","text":"Les autres conteneurs ne pourront plus la joindre"},{"id":"c","text":"Aucun, Docker isole toujours les ports publiés"},{"id":"d","text":"La base sera plus lente"}],"answer":["a"],"explanation":"Publier un port l’ouvre sur toutes les interfaces de l’hôte, et Docker insère des règles iptables qui contournent souvent ufw. Si seuls les conteneurs ont besoin de la base, on ne publie rien ; sinon on limite à 127.0.0.1:5432:5432.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"ac0cc3cf-046d-5398-87bd-330fdc2b5fd9","type":"multiple","prompt":"Avant de mettre à jour l’image d’un service en production, cochez les précautions utiles.","choices":[{"id":"a","text":"Mettre à jour directement en production sans tester ailleurs"},{"id":"b","text":"Lire les notes de version, notamment les changements de configuration ou de schéma"},{"id":"c","text":"Noter l’étiquette actuellement déployée pour pouvoir revenir en arrière"},{"id":"d","text":"Supprimer l’ancienne image avant d’avoir validé la nouvelle"}],"answer":["b","c"],"explanation":"Connaître la version actuelle et lire ce qui change sont les deux conditions d’un retour arrière rapide et d’une mise à jour sans surprise. Supprimer l’ancienne image trop tôt ou sauter l’essai préalable retire justement ces filets de sécurité.","difficulty":"intermediate","platform":"docker"}$q$::jsonb),
    ($q${"id":"e6bc7270-9b00-5fd9-90f4-34d0d7ad6307","type":"single","prompt":"Sur quoi repose l’isolation d’un conteneur Linux ?","choices":[{"id":"a","text":"Sur un pare-feu intégré à chaque image"},{"id":"b","text":"Sur un hyperviseur qui démarre un noyau dédié par conteneur"},{"id":"c","text":"Sur des mécanismes du noyau de l’hôte : namespaces pour la visibilité, cgroups pour les ressources"},{"id":"d","text":"Sur le chiffrement des fichiers du conteneur"}],"answer":["c"],"explanation":"Les namespaces séparent ce que voit le processus (PID, réseau, montages, utilisateurs) et les cgroups limitent CPU et mémoire. Tous les conteneurs partagent le noyau de l’hôte, ce qui les rend légers mais moins isolés qu’une machine virtuelle.","difficulty":"advanced","platform":"docker"}$q$::jsonb),
    ($q${"id":"d0c88889-aa7e-5efa-86e8-5d9a2f22852d","type":"single","prompt":"`/var/log/auth.log` montre des milliers de « Failed password for root » venant de quelques adresses. Quelle réponse est la plus adaptée en premier ?","choices":[{"id":"a","text":"Vérifier qu’aucune connexion n’a réussi, puis interdire la connexion root et par mot de passe et limiter les tentatives (fail2ban)"},{"id":"b","text":"Changer le port SSH et considérer le problème réglé"},{"id":"c","text":"Supprimer le fichier auth.log pour libérer de la place"},{"id":"d","text":"Éteindre le serveur"}],"answer":["a"],"explanation":"On vérifie d’abord s’il y a eu une compromission (lignes « Accepted »), puis on réduit la surface : clés seulement, pas de root, blocage des adresses insistantes. Changer de port réduit le bruit mais ne protège pas. Effacer le journal détruit des preuves.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"906d8fe9-db96-524d-8651-27b950cba243","type":"multiple","prompt":"Vous allez passer SSH en `PasswordAuthentication no` sur un serveur distant. Cochez les précautions indispensables.","choices":[{"id":"a","text":"Supprimer toutes les clés existantes pour repartir proprement"},{"id":"b","text":"Garder une session SSH ouverte pendant le rechargement et tester depuis une seconde session"},{"id":"c","text":"Redémarrer le serveur pour appliquer la configuration"},{"id":"d","text":"Vérifier qu’une connexion par clé fonctionne pour votre compte avant d’appliquer"}],"answer":["b","d"],"explanation":"Sans clé valide, on se coupe l’accès. On teste la clé, on valide la configuration (sshd -t), on recharge sshd en gardant une session ouverte et on vérifie depuis une autre. Un redémarrage n’est pas nécessaire et supprimer les clés produit exactement la coupure qu’on veut éviter.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"3e9ee405-cdfa-5b31-b06b-048f8317dc0a","type":"single","prompt":"Que signifie le principe du moindre privilège ?","choices":[{"id":"a","text":"Les administrateurs doivent avoir le moins d’outils possible"},{"id":"b","text":"Chaque compte ou service ne reçoit que les droits strictement nécessaires à sa tâche"},{"id":"c","text":"Les utilisateurs doivent changer de mot de passe chaque semaine"},{"id":"d","text":"Il faut désactiver tous les comptes inutilisés une fois par an"}],"answer":["b"],"explanation":"Limiter les droits limite ce qu’un attaquant peut faire avec un compte compromis et ce qu’une erreur peut casser. Désactiver les comptes inutiles en découle, mais le principe s’applique en continu, pas une fois par an.","difficulty":"beginner","platform":"security"}$q$::jsonb),
    ($q${"id":"18fc3bfa-df60-55c2-a072-157a92842869","type":"single","prompt":"Un audit trouve une clé privée SSH en mode 644 dans le répertoire d’un compte de service. Que faire ?","choices":[{"id":"a","text":"Ne rien faire si personne ne s’en est plaint"},{"id":"b","text":"Renommer le fichier pour le cacher"},{"id":"c","text":"Restreindre ses droits (600), puis considérer la clé comme exposée : la remplacer et retirer l’ancienne des authorized_keys"},{"id":"d","text":"Passer seulement le fichier en 600"}],"answer":["c"],"explanation":"Tant qu’elle était lisible par tous, n’importe quel compte a pu la copier. Corriger les droits empêche les copies futures, pas les copies passées : on fait tourner la clé. Renommer ne change pas les droits.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"840b9ebe-a606-573b-9306-468214a23efd","type":"single","prompt":"Vous soupçonnez qu’un serveur est compromis. Quelle est la bonne première attitude ?","choices":[{"id":"a","text":"Réinstaller le système tout de suite"},{"id":"b","text":"Redémarrer pour arrêter les processus malveillants"},{"id":"c","text":"Isoler la machine du réseau en la gardant allumée, préserver les journaux et la mémoire, puis analyser"},{"id":"d","text":"Supprimer immédiatement les fichiers suspects"}],"answer":["c"],"explanation":"Isoler arrête la propagation ; garder la machine allumée conserve la mémoire et les connexions en cours. Supprimer, redémarrer ou réinstaller détruit les éléments qui diront comment l’attaquant est entré, et donc comment l’empêcher de revenir.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"04887bdf-dbf1-5543-bd96-7213a2e54e7f","type":"single","prompt":"Que fait fail2ban ?","choices":[{"id":"a","text":"Il surveille les journaux et bannit temporairement, via le pare-feu, les adresses qui accumulent les échecs"},{"id":"b","text":"Il remplace le pare-feu du système"},{"id":"c","text":"Il corrige les failles des logiciels installés"},{"id":"d","text":"Il chiffre les mots de passe des utilisateurs"}],"answer":["a"],"explanation":"fail2ban lit des journaux (SSH, serveur web…), repère les motifs d’échec et ajoute des règles de blocage pour une durée donnée. Il s’appuie sur le pare-feu existant et ne corrige aucune vulnérabilité.","difficulty":"beginner","platform":"security"}$q$::jsonb),
    ($q${"id":"b9191a44-a874-5f0e-af6f-46c6dc558565","type":"single","prompt":"Pourquoi stocker les mots de passe avec un algorithme comme bcrypt ou Argon2 plutôt qu’avec SHA-256 seul ?","choices":[{"id":"a","text":"Parce que SHA-256 est réversible"},{"id":"b","text":"Parce que bcrypt chiffre le mot de passe avec une clé qu’on peut redemander"},{"id":"c","text":"Parce que SHA-256 produit des empreintes trop longues"},{"id":"d","text":"Parce qu’ils sont volontairement lents et salés, ce qui rend les attaques par dictionnaire beaucoup plus coûteuses"}],"answer":["d"],"explanation":"SHA-256 n’est pas réversible, mais il est très rapide : on peut tester des milliards de mots de passe par seconde. bcrypt et Argon2 ajoutent un sel unique et un coût réglable. On ne chiffre pas les mots de passe : on les hache.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"fe9c9d48-43cb-5cad-ab6d-fd739782ce6f","type":"single","prompt":"Pourquoi l’authentification multifacteur (MFA) réduit-elle fortement le risque lié aux mots de passe volés ?","choices":[{"id":"a","text":"Parce qu’elle bloque les adresses IP étrangères"},{"id":"b","text":"Parce qu’elle chiffre le mot de passe"},{"id":"c","text":"Parce qu’elle oblige à changer de mot de passe chaque jour"},{"id":"d","text":"Parce que le mot de passe seul ne suffit plus : il faut aussi un second facteur que l’attaquant ne possède pas"}],"answer":["d"],"explanation":"Un mot de passe hameçonné ou réutilisé ne donne plus l’accès sans le second facteur (application, clé physique). Les clés FIDO2 résistent en plus à l’hameçonnage. La MFA ne chiffre rien et n’impose pas de rotation.","difficulty":"beginner","platform":"security"}$q$::jsonb),
    ($q${"id":"04caa915-55e7-554b-a95f-4038d30db1e3","type":"single","prompt":"Une alerte signale que le binaire `/usr/bin/ps` a changé alors qu’aucune mise à jour n’a eu lieu. Quel outil aide à le confirmer ?","choices":[{"id":"a","text":"ping"},{"id":"b","text":"La commande ps elle-même"},{"id":"c","text":"top"},{"id":"d","text":"Un contrôle d’intégrité (AIDE, ou la vérification des paquets : debsums, rpm -V)"}],"answer":["d"],"explanation":"On compare les empreintes des fichiers avec une référence (base AIDE ou empreintes du paquet). Interroger le binaire suspect avec lui-même ne prouve rien : un rootkit modifie justement ps pour cacher ses processus.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"2af330d1-2eb0-5510-823e-98889d30b781","type":"multiple","prompt":"Cochez les bonnes pratiques de gestion des secrets d’une application.","choices":[{"id":"a","text":"Partager le mot de passe de production par messagerie pour gagner du temps"},{"id":"b","text":"Utiliser le même mot de passe sur tous les environnements pour simplifier"},{"id":"c","text":"Faire tourner un secret dès qu’il a pu être exposé"},{"id":"d","text":"Ne jamais committer de secret dans le dépôt de code"}],"answer":["c","d"],"explanation":"Un secret dans l’historique Git reste lisible même après suppression du fichier. Un secret exposé se remplace. Les messageries conservent les messages, et un mot de passe commun fait qu’une fuite en recette compromet la production.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"a7454930-a546-579d-bfa8-4682e2e1166e","type":"single","prompt":"Une page de connexion affiche « mot de passe incorrect » pour un compte existant et « utilisateur inconnu » sinon. Quel problème cela pose-t-il ?","choices":[{"id":"a","text":"Aucun, c’est plus clair pour l’utilisateur"},{"id":"b","text":"Il empêche la MFA de fonctionner"},{"id":"c","text":"Il permet d’énumérer les comptes valides, ce qui facilite les attaques ciblées"},{"id":"d","text":"Il ralentit la connexion"}],"answer":["c"],"explanation":"Un attaquant teste des noms et repère ceux qui existent, puis concentre ses tentatives sur eux. On renvoie un message unique (« identifiants incorrects ») et un temps de réponse comparable dans les deux cas.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"2396f477-27e2-5be3-916c-2766be6d9cda","type":"single","prompt":"Comment se protéger d’une injection SQL dans une application ?","choices":[{"id":"a","text":"Masquer les messages d’erreur de la base"},{"id":"b","text":"Utiliser des requêtes paramétrées : les valeurs sont transmises séparément du texte SQL"},{"id":"c","text":"Supprimer les apostrophes des saisies"},{"id":"d","text":"Utiliser HTTPS"}],"answer":["b"],"explanation":"Avec une requête paramétrée, la base ne peut pas interpréter une valeur comme du SQL. Filtrer des caractères se contourne, masquer les erreurs ne fait que gêner l’attaquant, et HTTPS protège le transport, pas la requête.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"cf16f357-376c-57e3-962a-74ec0b6fcb53","type":"single","prompt":"Qu’apporte HTTPS (TLS) entre un navigateur et un site ?","choices":[{"id":"a","text":"L’anonymat complet de l’utilisateur"},{"id":"b","text":"La protection contre les mots de passe faibles"},{"id":"c","text":"La confidentialité et l’intégrité des échanges, et la vérification que le serveur est bien celui du nom demandé"},{"id":"d","text":"La garantie que le site n’a aucune faille"}],"answer":["c"],"explanation":"TLS chiffre le trafic, détecte sa modification et authentifie le serveur par son certificat. Il ne dit rien de la sécurité de l’application elle-même, ni de la robustesse des mots de passe, et ne rend pas anonyme.","difficulty":"beginner","platform":"security"}$q$::jsonb),
    ($q${"id":"2d1e7460-6f73-5aab-b9c4-a6fcd6aba5cf","type":"single","prompt":"Pourquoi centraliser les journaux de plusieurs serveurs sur un système séparé ?","choices":[{"id":"a","text":"Pour corréler les événements et pour qu’un attaquant qui prend la main sur un serveur ne puisse pas effacer ses traces"},{"id":"b","text":"Parce que les journaux locaux sont chiffrés"},{"id":"c","text":"Pour accélérer les serveurs"},{"id":"d","text":"Pour libérer de l’espace disque sur les serveurs uniquement"}],"answer":["a"],"explanation":"Un attaquant efface souvent les journaux locaux. Une copie envoyée au fil de l’eau vers un système séparé reste exploitable, et voir les journaux de toutes les machines ensemble révèle un mouvement d’un serveur à l’autre.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"a01149a8-2a88-507d-8451-595353510d97","type":"multiple","prompt":"Cochez les mesures de durcissement pertinentes pour un serveur web Linux exposé à Internet.","choices":[{"id":"a","text":"Ne laisser ouverts au pare-feu que les ports nécessaires (443, et SSH restreint)"},{"id":"b","text":"Désactiver les journaux pour gagner en performance"},{"id":"c","text":"Appliquer régulièrement les mises à jour de sécurité"},{"id":"d","text":"Faire tourner le serveur web en root pour éviter les problèmes de droits"}],"answer":["a","c"],"explanation":"Corriger les failles connues et réduire la surface exposée sont les deux bases du durcissement. Sans journaux, on ne détecte rien ; un service en root transforme toute faille applicative en prise de contrôle complète.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"4a0ff9d7-1165-557f-8a9a-0127968c4c2d","type":"single","prompt":"Une sauvegarde est-elle utile contre un rançongiciel si elle est montée en permanence sur le serveur sauvegardé ?","choices":[{"id":"a","text":"Non, aucune sauvegarde ne protège contre un rançongiciel"},{"id":"b","text":"Oui, tant qu’elle est sur un autre disque"},{"id":"c","text":"Peu : le rançongiciel chiffrera aussi la sauvegarde ; il faut une copie hors ligne ou immuable"},{"id":"d","text":"Oui, les sauvegardes ne peuvent pas être chiffrées"}],"answer":["c"],"explanation":"Tout ce que le serveur peut écrire, le rançongiciel peut le chiffrer. La règle 3-2-1 prévoit au moins une copie hors site et une copie hors ligne ou immuable. Et on teste régulièrement la restauration.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"75fb9e43-7adf-5a02-81ca-c3dfca08e1fb","type":"single","prompt":"Un utilisateur reçoit un courriel « urgent » de la direction lui demandant ses identifiants. Quel réflexe enseigner ?","choices":[{"id":"a","text":"Répondre en demandant plus de détails"},{"id":"b","text":"Transférer le message à toute l’équipe pour prévenir"},{"id":"c","text":"Ne pas répondre, vérifier la demande par un autre canal connu et signaler le message"},{"id":"d","text":"Cliquer sur le lien pour vérifier s’il est légitime"}],"answer":["c"],"explanation":"L’urgence et l’autorité sont les ressorts habituels de l’hameçonnage. On vérifie auprès de la personne par téléphone ou en interne, et on signale pour que l’équipe sécurité bloque la campagne. Transférer le message propage le piège.","difficulty":"beginner","platform":"security"}$q$::jsonb),
    ($q${"id":"fb5d58ef-91e4-5d9f-8c0d-b564ca52bdf4","type":"single","prompt":"Le scanner de vulnérabilités signale une faille critique sur un logiciel exposé, mais le correctif n’est pas encore disponible. Que faire ?","choices":[{"id":"a","text":"Attendre le correctif sans rien changer"},{"id":"b","text":"Ignorer l’alerte si le service fonctionne"},{"id":"c","text":"Appliquer une mesure de contournement (désactiver la fonction, filtrer l’accès), surveiller, puis corriger dès que possible"},{"id":"d","text":"Désinstaller le scanner pour faire disparaître l’alerte"}],"answer":["c"],"explanation":"Sans correctif, on réduit l’exposition : contournement recommandé par l’éditeur, restriction d’accès, surveillance accrue des journaux. Attendre ou ignorer laisse la faille ouverte.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"a1d685e0-4f9f-5896-b868-2a9e64a328eb","type":"single","prompt":"Que doit contenir en priorité le compte rendu d’un incident de sécurité ?","choices":[{"id":"a","text":"Uniquement la liste des fichiers supprimés"},{"id":"b","text":"Rien, l’incident étant clos"},{"id":"c","text":"La chronologie, la cause, l’impact, les actions menées et les mesures pour éviter que cela se reproduise"},{"id":"d","text":"Le nom de la personne responsable de l’erreur"}],"answer":["c"],"explanation":"Un retour d’expérience sert à apprendre et à corriger le système, pas à désigner un coupable. Sans chronologie ni cause, les mêmes faiblesses restent en place.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"06c7a578-73bb-5348-a641-d728c0c7eb7a","type":"single","prompt":"Un processus inconnu écoute sur un port élevé. Quelle démarche permet de comprendre ce qu’il est sans le perturber ?","choices":[{"id":"a","text":"Redémarrer le serveur"},{"id":"b","text":"Identifier le processus (ss -tlnp), son exécutable (/proc/<pid>/exe), son parent et ses connexions (lsof -p), avant toute action"},{"id":"c","text":"Le tuer immédiatement avec kill -9"},{"id":"d","text":"Supprimer son exécutable"}],"answer":["b"],"explanation":"On collecte d’abord : qui l’a lancé, depuis quel fichier, avec quelles connexions. Si c’est malveillant, ces éléments guident la réponse ; si c’est légitime, on évite une coupure. Tuer ou supprimer détruit les indices et peut casser un service.","difficulty":"advanced","platform":"security"}$q$::jsonb),
    ($q${"id":"6636e7b7-8eb2-5848-9058-266798661fa4","type":"single","prompt":"Pourquoi la segmentation du réseau limite-t-elle l’impact d’une intrusion ?","choices":[{"id":"a","text":"Parce qu’un poste compromis ne peut joindre que les systèmes de sa zone autorisés par les règles de filtrage"},{"id":"b","text":"Parce qu’elle remplace les mises à jour"},{"id":"c","text":"Parce qu’elle chiffre tout le trafic interne"},{"id":"d","text":"Parce qu’elle empêche l’hameçonnage"}],"answer":["a"],"explanation":"En séparant postes, serveurs et administration, et en filtrant les flux entre zones, on empêche un attaquant de rebondir librement. La segmentation ne chiffre rien et ne dispense ni de sensibiliser ni de mettre à jour.","difficulty":"advanced","platform":"security"}$q$::jsonb),
    ($q${"id":"fef38665-6232-5347-b646-66628ef8bc63","type":"single","prompt":"Que vaut un mot de passe long et unique stocké dans un gestionnaire de mots de passe, par rapport à un mot de passe court réutilisé partout ?","choices":[{"id":"a","text":"Il résiste mieux aux attaques par essais et une fuite sur un site ne compromet pas les autres comptes"},{"id":"b","text":"Il est équivalent"},{"id":"c","text":"Il est interdit par la plupart des politiques de sécurité"},{"id":"d","text":"Il est moins sûr car il est écrit quelque part"}],"answer":["a"],"explanation":"La longueur rend les essais trop coûteux et l’unicité empêche la réutilisation d’une fuite (credential stuffing). Le gestionnaire est chiffré par un mot de passe maître, idéalement protégé par la MFA.","difficulty":"beginner","platform":"security"}$q$::jsonb),
    ($q${"id":"a93a8a85-6588-551f-952d-fa7ed0b68c21","type":"single","prompt":"Les journaux d’un serveur web montrent des requêtes comme `GET /../../etc/passwd`. Que tentent-elles ?","choices":[{"id":"a","text":"Une injection SQL"},{"id":"b","text":"Une traversée de répertoires, pour lire des fichiers hors du dossier publié"},{"id":"c","text":"Une attaque par déni de service"},{"id":"d","text":"Une mise à jour automatique du serveur"}],"answer":["b"],"explanation":"Les ../ cherchent à remonter l’arborescence pour atteindre des fichiers système. On vérifie les réponses renvoyées (un code 200 avec du contenu serait grave), on s’assure que le serveur normalise les chemins et on surveille l’adresse source.","difficulty":"intermediate","platform":"security"}$q$::jsonb),
    ($q${"id":"b3b67581-289e-5c46-87ed-793aba09891d","type":"multiple","prompt":"Un compte administrateur a été utilisé depuis un pays inhabituel en pleine nuit. Cochez les actions appropriées.","choices":[{"id":"a","text":"Examiner les actions effectuées pendant la session suspecte"},{"id":"b","text":"Attendre de voir si cela se reproduit"},{"id":"c","text":"Supprimer le compte et ses journaux pour repartir sur une base propre"},{"id":"d","text":"Révoquer les sessions actives et réinitialiser les identifiants du compte"}],"answer":["a","d"],"explanation":"On coupe l’accès de l’attaquant, puis on mesure ce qu’il a pu faire (créations de comptes, changements de droits, exfiltration). Supprimer les journaux empêche cette analyse, et attendre lui laisse le temps de s’installer durablement.","difficulty":"advanced","platform":"security"}$q$::jsonb),
    ($q${"id":"1d016083-21a5-5562-95d8-0556850d74ee","type":"single","prompt":"Un poste Windows démarre très lentement depuis l’installation d’un logiciel. Où regarder d’abord ?","choices":[{"id":"a","text":"Dans le Gestionnaire des tâches, onglet Démarrage, pour voir les programmes lancés à l’ouverture de session et leur impact"},{"id":"b","text":"Dans l’Observateur d’événements, pour effacer les journaux"},{"id":"c","text":"Dans l’Éditeur du Registre, pour supprimer les clés du logiciel"},{"id":"d","text":"Dans le Panneau de configuration, pour réinitialiser Windows"}],"answer":["a"],"explanation":"L’onglet Démarrage liste ce qui se lance à l’ouverture de session et estime son impact : on désactive un élément sans rien supprimer, et on peut revenir en arrière. Modifier le Registre à la main ou réinitialiser Windows est disproportionné ; effacer les journaux détruit des indices.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"fb31e8e9-98f2-5622-8950-0e2e984e654e","type":"single","prompt":"Que fait la commande `sfc /scannow` ?","choices":[{"id":"a","text":"Elle vérifie les fichiers système protégés et remplace ceux qui sont corrompus par une copie saine"},{"id":"b","text":"Elle libère de l’espace disque"},{"id":"c","text":"Elle recherche des virus"},{"id":"d","text":"Elle analyse le disque à la recherche de secteurs défectueux"}],"answer":["a"],"explanation":"SFC (System File Checker) compare les fichiers système à leur version de référence et les restaure depuis le magasin de composants. Les secteurs du disque relèvent de chkdsk, les virus de l’antivirus et l’espace disque du Nettoyage de disque.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"2b9d18ce-8145-5611-8cd1-90a59a1f2291","type":"single","prompt":"`sfc /scannow` signale des fichiers corrompus qu’il n’a pas pu réparer. Que lancer ensuite ?","choices":[{"id":"a","text":"`DISM /Online /Cleanup-Image /RestoreHealth`, pour réparer le magasin de composants, puis relancer sfc"},{"id":"b","text":"chkdsk /f immédiatement, puis réinstaller Windows"},{"id":"c","text":"Désactiver le contrôle de compte d’utilisateur"},{"id":"d","text":"Supprimer les fichiers signalés"}],"answer":["a"],"explanation":"SFC répare à partir du magasin de composants : si celui-ci est abîmé, SFC échoue. DISM répare ce magasin (depuis Windows Update ou une source fournie), après quoi SFC peut terminer. Supprimer des fichiers système aggraverait la situation.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"a9415aa3-5692-5fff-ba02-f7e9e5fb3e63","type":"single","prompt":"Un utilisateur a supprimé par erreur un pilote et le poste fonctionne mal depuis. Quelle fonction permet de revenir à l’état de la veille sans toucher à ses documents ?","choices":[{"id":"a","text":"La Restauration du système, vers un point de restauration antérieur"},{"id":"b","text":"Le formatage de la partition système"},{"id":"c","text":"L’Historique des fichiers"},{"id":"d","text":"La réinitialisation complète du PC en supprimant tout"}],"answer":["a"],"explanation":"Un point de restauration ramène les fichiers système, les pilotes et le Registre à un état antérieur sans toucher aux documents personnels. L’Historique des fichiers sert à l’inverse à récupérer des documents ; réinitialiser ou formater fait perdre bien plus que nécessaire.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"4d94b8e5-73a5-5db7-9acc-9ac523d2ee88","type":"single","prompt":"Un périphérique apparaît avec un triangle jaune dans le Gestionnaire de périphériques. Qu’est-ce que cela signifie ?","choices":[{"id":"a","text":"Le périphérique est neuf"},{"id":"b","text":"Le périphérique est désactivé volontairement"},{"id":"c","text":"Windows a détecté un problème avec ce périphérique, souvent un pilote absent ou défectueux ; ses propriétés donnent un code d’erreur"},{"id":"d","text":"Le périphérique fonctionne mais une mise à jour de Windows est disponible"}],"answer":["c"],"explanation":"Le triangle jaune signale un problème ; l’onglet Général des propriétés indique un code (par exemple 10 ou 43) qui oriente le diagnostic. Un périphérique désactivé porte une flèche vers le bas, pas un triangle.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"0b11dc70-5156-52a9-8564-61f3e8dcb9fe","type":"single","prompt":"Depuis la mise à jour d’un pilote graphique, l’écran clignote. Quelle est l’action la plus ciblée ?","choices":[{"id":"a","text":"Changer la résolution au maximum"},{"id":"b","text":"Réinstaller Windows"},{"id":"c","text":"Revenir au pilote précédent depuis les propriétés du périphérique (bouton « Restaurer le pilote »)"},{"id":"d","text":"Désinstaller toutes les mises à jour de Windows"}],"answer":["c"],"explanation":"Le changement qui précède la panne est connu : on l’annule précisément. La restauration du pilote réinstalle la version précédente sans toucher au reste. Les autres actions sont soit disproportionnées, soit sans rapport.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"9b99589f-1831-5980-b24f-8b44e3260676","type":"single","prompt":"Où trouver le détail d’une erreur d’application qui s’est produite hier ?","choices":[{"id":"a","text":"Dans le Gestionnaire des tâches"},{"id":"b","text":"Dans la corbeille"},{"id":"c","text":"Dans les Paramètres, rubrique Personnalisation"},{"id":"d","text":"Dans l’Observateur d’événements, journal Windows « Application »"}],"answer":["d"],"explanation":"L’Observateur d’événements conserve l’historique des erreurs avec leur date, leur source et leur identifiant. Le Gestionnaire des tâches ne montre que l’état actuel.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"44076103-0ab1-512f-b742-cd17f6e68a6c","type":"single","prompt":"Un poste affiche un écran bleu avec le code `CRITICAL_PROCESS_DIED` après une coupure de courant. Quelle première démarche est raisonnable ?","choices":[{"id":"a","text":"Démarrer l’environnement de récupération (WinRE), tenter la réparation du démarrage puis vérifier le disque et les fichiers système"},{"id":"b","text":"Formater le disque sans sauvegarde"},{"id":"c","text":"Remplacer immédiatement la carte mère"},{"id":"d","text":"Ignorer le message et redémarrer en boucle jusqu’à ce que cela passe"}],"answer":["a"],"explanation":"Une coupure en pleine écriture peut corrompre des fichiers système. WinRE donne accès à la réparation du démarrage, à chkdsk, à sfc hors ligne et à la restauration du système. On ne remplace pas de matériel et on n’efface rien avant d’avoir écarté une réparation logicielle.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"ab501b25-eaa9-5d45-b3b1-c01cd3e90fca","type":"single","prompt":"Quelle commande affiche l’adresse IP, la passerelle et les serveurs DNS d’un poste Windows ?","choices":[{"id":"a","text":"ipconfig /all"},{"id":"b","text":"netstat"},{"id":"c","text":"tracert"},{"id":"d","text":"ping"}],"answer":["a"],"explanation":"ipconfig /all détaille la configuration de chaque carte (adresse, masque, passerelle, DNS, DHCP). ping teste une destination, netstat liste les connexions et tracert montre le chemin vers une destination.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"46c6b230-7e6b-520f-9cdc-a16f9b60e031","type":"single","prompt":"Un poste accède aux sites par adresse IP mais pas par nom. Quelle commande teste directement la résolution d’un nom ?","choices":[{"id":"a","text":"ipconfig /release"},{"id":"b","text":"chkdsk"},{"id":"c","text":"sfc /scannow"},{"id":"d","text":"nslookup exemple.fr"}],"answer":["d"],"explanation":"nslookup interroge le serveur DNS configuré et montre sa réponse, ce qui confirme ou écarte la piste DNS. ipconfig /release rend l’adresse IP, et chkdsk ou sfc concernent le disque et les fichiers système.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"1b2912cc-0a0c-53de-84f3-a5eb8a7ae0be","type":"single","prompt":"Après avoir corrigé un serveur DNS, un poste continue d’aller vers l’ancienne adresse d’un site. Quelle commande aide ?","choices":[{"id":"a","text":"ipconfig /renew"},{"id":"b","text":"netsh winsock reset"},{"id":"c","text":"shutdown /r"},{"id":"d","text":"ipconfig /flushdns"}],"answer":["d"],"explanation":"Le poste garde les réponses DNS en cache : /flushdns le vide et force une nouvelle résolution. /renew redemande une adresse IP au DHCP, et réinitialiser Winsock ou redémarrer sont plus lourds que nécessaire.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"6c21e923-6356-5866-87f3-a33d2a66a0b0","type":"single","prompt":"Un utilisateur demande les droits administrateur sur son poste pour installer un logiciel. Quelle réponse privilégier ?","choices":[{"id":"a","text":"Désactiver le contrôle de compte d’utilisateur"},{"id":"b","text":"L’ajouter au groupe Administrateurs définitivement"},{"id":"c","text":"Lui donner le mot de passe du compte administrateur local"},{"id":"d","text":"Installer le logiciel pour lui (ou le publier via l’outil de déploiement) sans lui donner de droits permanents"}],"answer":["d"],"explanation":"Un compte standard limite les dégâts d’un logiciel malveillant ou d’une erreur. On répond au besoin (installer ce logiciel) sans accorder plus. Partager le mot de passe administrateur ou désactiver l’UAC affaiblit tout le poste.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"d37df4ea-66c4-52cf-b6f2-e6cebd858def","type":"single","prompt":"Que protège BitLocker ?","choices":[{"id":"a","text":"Le poste contre les virus"},{"id":"b","text":"Les données d’un disque en cas de vol ou de perte du poste, en les chiffrant"},{"id":"c","text":"Les documents contre une suppression accidentelle"},{"id":"d","text":"Le réseau contre les intrusions"}],"answer":["b"],"explanation":"BitLocker chiffre le volume : sans la clé (TPM, code PIN ou clé de récupération), le disque retiré du poste est illisible. Il ne remplace ni l’antivirus, ni la sauvegarde, ni le pare-feu. La clé de récupération doit être conservée ailleurs que sur le poste.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"b9eccd9e-6f1c-5cb3-adf1-f02134975a2c","type":"single","prompt":"Au démarrage, BitLocker demande la clé de récupération après une mise à jour du BIOS. Où l’utilisateur peut-elle se trouver ?","choices":[{"id":"a","text":"Là où elle a été sauvegardée à l’activation : Active Directory, Entra ID, compte Microsoft ou copie imprimée"},{"id":"b","text":"Dans le BIOS lui-même"},{"id":"c","text":"Dans un fichier sur le disque chiffré"},{"id":"d","text":"Nulle part : le disque est définitivement perdu"}],"answer":["a"],"explanation":"Un changement du firmware modifie les mesures du TPM, qui ne libère plus la clé automatiquement. La clé de récupération est conservée au moment de l’activation, idéalement dans l’annuaire de l’entreprise. Une copie stockée sur le disque chiffré serait inaccessible.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"3a96575a-1c49-50a9-93d8-bc32c9431236","type":"single","prompt":"Le disque C: est presque plein. Quelle action libère de la place sans risque pour les données de l’utilisateur ?","choices":[{"id":"a","text":"Supprimer le dossier C:\\Windows\\System32"},{"id":"b","text":"Le Nettoyage de disque (ou Assistant de stockage) pour les fichiers temporaires et les anciennes mises à jour"},{"id":"c","text":"Vider le dossier Documents"},{"id":"d","text":"Désactiver la mémoire virtuelle"}],"answer":["b"],"explanation":"Ces outils ne proposent que des éléments sans conséquence (fichiers temporaires, cache de mises à jour, corbeille). Supprimer System32 rend Windows inutilisable, désactiver la mémoire virtuelle provoque des plantages, et les documents appartiennent à l’utilisateur.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"07c8bec5-e174-5da8-8f8b-2f9b44f858e3","type":"single","prompt":"Une imprimante réseau partagée n’imprime plus : les documents restent « en attente ». Quelle démarche est la plus efficace ?","choices":[{"id":"a","text":"Changer le câble réseau du poste"},{"id":"b","text":"Supprimer tous les pilotes de tous les postes"},{"id":"c","text":"Vérifier que l’imprimante répond (ping, page web), puis vider la file et redémarrer le service Spouleur d’impression"},{"id":"d","text":"Réinstaller Windows sur le poste"}],"answer":["c"],"explanation":"On vérifie d’abord que l’imprimante est joignable, puis on traite le blocage le plus fréquent : un travail coincé dans le spouleur. Redémarrer le service Spouleur libère la file. Les autres actions sont disproportionnées ou ne visent pas la cause.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"31fa5050-afbe-58e5-9bed-383666a0df37","type":"multiple","prompt":"Un utilisateur signale des fenêtres publicitaires et un navigateur dont la page d’accueil a changé. Cochez les actions appropriées.","choices":[{"id":"a","text":"Vérifier les extensions du navigateur et les programmes installés récemment"},{"id":"b","text":"Déconnecter le poste du réseau si un comportement suspect se poursuit, puis lancer une analyse antivirus complète"},{"id":"c","text":"Ignorer, c’est un comportement normal de Windows"},{"id":"d","text":"Désactiver l’antivirus pour accélérer le nettoyage"}],"answer":["a","b"],"explanation":"Ces symptômes évoquent un logiciel indésirable : on l’identifie (extension, logiciel installé avec un autre) et on analyse le poste. Désactiver l’antivirus ou ignorer laisse le problème s’étendre.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"90b84d05-33f3-5cee-ab78-a091fae46a05","type":"single","prompt":"Que permet le mode sans échec ?","choices":[{"id":"a","text":"Réinstaller Windows automatiquement"},{"id":"b","text":"Désactiver définitivement les mises à jour"},{"id":"c","text":"Démarrer Windows sans mot de passe"},{"id":"d","text":"Démarrer Windows avec un minimum de pilotes et de services pour isoler un problème causé par un logiciel ou un pilote"}],"answer":["d"],"explanation":"Si le problème disparaît en mode sans échec, il vient d’un élément qui ne s’y charge pas (pilote, logiciel au démarrage). C’est un outil de diagnostic, pas un contournement du mot de passe ni une réinstallation.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"5f2763c5-f661-5a77-8ac7-af64c0444f7f","type":"single","prompt":"Le Gestionnaire des tâches montre un disque à 100 % d’utilisation en permanence. Quel outil donne le détail des fichiers et processus qui l’utilisent ?","choices":[{"id":"a","text":"msconfig"},{"id":"b","text":"La Calculatrice"},{"id":"c","text":"Le Moniteur de ressources (resmon)"},{"id":"d","text":"Le Panneau de configuration"}],"answer":["c"],"explanation":"Le Moniteur de ressources détaille, pour le disque, les processus et les fichiers lus ou écrits avec leur débit. Cela permet d’identifier une indexation, une mise à jour ou un logiciel en cause avant d’agir.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"1e5ec31a-2e0f-5d19-8634-871469bf3b27","type":"single","prompt":"Quelle est la différence entre un compte local et un compte de domaine sur un poste d’entreprise ?","choices":[{"id":"a","text":"Le compte local n’existe que sur ce poste ; le compte de domaine est géré centralement par Active Directory et utilisable sur les postes du domaine"},{"id":"b","text":"Il n’y a aucune différence"},{"id":"c","text":"Le compte local est toujours administrateur"},{"id":"d","text":"Le compte de domaine n’a jamais de mot de passe"}],"answer":["a"],"explanation":"Le compte de domaine est authentifié par un contrôleur de domaine, qui applique aussi les stratégies de groupe. Un compte local est stocké sur le poste. Ni l’un ni l’autre n’est administrateur par défaut.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"5ffbe6d0-436e-5f34-be4c-e1fdda57237a","type":"single","prompt":"Un utilisateur ne retrouve plus un fichier modifié la semaine dernière sur son poste. Quelle fonction permet de récupérer une version précédente, si elle était activée ?","choices":[{"id":"a","text":"sfc /scannow"},{"id":"b","text":"Le Gestionnaire de périphériques"},{"id":"c","text":"L’Historique des fichiers (versions précédentes)"},{"id":"d","text":"La Restauration du système"}],"answer":["c"],"explanation":"L’Historique des fichiers copie régulièrement les documents vers un autre support et permet d’en restaurer une version. La Restauration du système concerne les fichiers système et ne récupère pas les documents ; sfc répare les fichiers de Windows.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"f2c4eed2-601d-5064-864d-a64bd8935c97","type":"single","prompt":"Un poste n’arrive plus à ouvrir de session de domaine (« la relation d’approbation entre cette station de travail et le domaine principal a échoué »). Que se passe-t-il ?","choices":[{"id":"a","text":"Le câble réseau est débranché"},{"id":"b","text":"Le disque est plein"},{"id":"c","text":"Le mot de passe du compte ordinateur n’est plus synchronisé avec Active Directory ; il faut réparer ou refaire la jonction au domaine"},{"id":"d","text":"Le mot de passe de l’utilisateur a expiré"}],"answer":["c"],"explanation":"Chaque poste du domaine a un compte ordinateur avec son propre mot de passe. Après une restauration ancienne ou une longue absence, il peut diverger : Test-ComputerSecureChannel -Repair ou une nouvelle jonction le rétablit. Un mot de passe utilisateur expiré donne un autre message.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"c4b2f3d2-f0b1-582b-b746-3d42aed3417a","type":"multiple","prompt":"Avant de réparer le poste d’un utilisateur, cochez les bonnes pratiques.","choices":[{"id":"a","text":"Supprimer son profil par précaution"},{"id":"b","text":"Noter ce qui a été modifié, pour pouvoir revenir en arrière et documenter l’intervention"},{"id":"c","text":"Tester plusieurs corrections à la fois pour gagner du temps"},{"id":"d","text":"Vérifier que ses données importantes sont sauvegardées"}],"answer":["b","d"],"explanation":"La sauvegarde protège l’utilisateur, et la trace des changements permet de revenir en arrière et de comprendre ce qui a corrigé le problème. Plusieurs corrections à la fois empêchent de savoir laquelle a fonctionné ; supprimer un profil fait perdre des données.","difficulty":"beginner","platform":"windows"}$q$::jsonb),
    ($q${"id":"ff965874-93f3-5f3e-a962-ee9e53dee889","type":"single","prompt":"Windows Update échoue toujours sur la même mise à jour avec un code d’erreur. Quelle démarche suivre ?","choices":[{"id":"a","text":"Rechercher le code d’erreur, lancer l’utilitaire de résolution des problèmes de Windows Update, puis vérifier l’espace disque et l’intégrité du système (DISM, sfc)"},{"id":"b","text":"Supprimer le dossier C:\\Windows"},{"id":"c","text":"Désactiver définitivement Windows Update"},{"id":"d","text":"Réinstaller Windows immédiatement"}],"answer":["a"],"explanation":"Le code d’erreur oriente le diagnostic ; les causes fréquentes sont le manque de place, un magasin de composants abîmé ou un cache de mises à jour corrompu. Désactiver les mises à jour laisse le poste vulnérable.","difficulty":"intermediate","platform":"windows"}$q$::jsonb),
    ($q${"id":"444a21f6-c821-5b87-8f56-887170ff8449","type":"single","prompt":"Les postes d’un domaine n’arrivent plus à ouvrir de session et les journaux parlent de contrôleur de domaine introuvable. Quel réglage réseau des postes vérifier en premier ?","choices":[{"id":"a","text":"Que leurs serveurs DNS soient les contrôleurs de domaine (ou les DNS internes), et non un DNS public"},{"id":"b","text":"Que leur adresse IP soit fixe"},{"id":"c","text":"Que le pare-feu Windows soit désactivé"},{"id":"d","text":"Que leur passerelle soit le contrôleur de domaine"}],"answer":["a"],"explanation":"Les postes trouvent les contrôleurs de domaine par des enregistrements SRV dans la zone DNS du domaine. Un DNS public ne connaît pas ces enregistrements. La passerelle et l’adressage fixe n’y jouent aucun rôle ; désactiver le pare-feu ne résout rien et expose le poste.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"0ccea793-eecb-58d1-98a2-9f2e50586535","type":"single","prompt":"Pourquoi un écart d’horloge de plus de cinq minutes entre un poste et le contrôleur de domaine empêche-t-il l’ouverture de session ?","choices":[{"id":"a","text":"Parce que les mots de passe expirent selon l’heure du poste"},{"id":"b","text":"Parce que DNS refuse les requêtes des postes en retard"},{"id":"c","text":"Parce que les GPO ne s’appliquent qu’à heure fixe"},{"id":"d","text":"Parce que Kerberos rejette les tickets dont l’horodatage s’écarte trop, pour se protéger du rejeu"}],"answer":["d"],"explanation":"Kerberos inclut l’heure dans ses échanges et refuse par défaut un écart supérieur à cinq minutes. Les postes se synchronisent sur la hiérarchie du domaine, dont la source est le contrôleur qui détient le rôle d’émulateur PDC, lui-même réglé sur une source de temps fiable.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"60dde0cc-88a0-5ccc-88fb-8d0286caf1c1","type":"single","prompt":"Dans quel ordre les stratégies de groupe sont-elles appliquées, la dernière l’emportant en cas de conflit ?","choices":[{"id":"a","text":"Locale, site, domaine, unité d’organisation (de la plus haute à la plus proche de l’objet)"},{"id":"b","text":"Domaine, locale, site, unité d’organisation"},{"id":"c","text":"Unité d’organisation, domaine, site, locale"},{"id":"d","text":"Dans l’ordre alphabétique des noms de GPO"}],"answer":["a"],"explanation":"On retient LSDOU : locale, site, domaine, puis les OU de la plus haute à la plus imbriquée. La dernière appliquée gagne, sauf si une GPO est « appliquée » (enforced) plus haut ou si l’héritage est bloqué.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"9ddd24f0-e2f9-5d28-bee5-f1f1717318c7","type":"single","prompt":"Une nouvelle GPO liée à l’OU « Comptabilité » ne s’applique pas à un poste de cette OU. Quelle commande montre, sur le poste, les GPO appliquées et celles filtrées ?","choices":[{"id":"a","text":"gpupdate /force"},{"id":"b","text":"gpresult /r (ou /h rapport.html)"},{"id":"c","text":"netstat -an"},{"id":"d","text":"ipconfig /all"}],"answer":["b"],"explanation":"gpresult indique les GPO appliquées et celles refusées avec la raison (filtrage de sécurité, filtre WMI, mauvaise partie utilisateur ou ordinateur). gpupdate force une actualisation, mais n’explique pas pourquoi une GPO est ignorée.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"a5d1eaa9-b835-5d3b-a1fc-f27fa25e461f","type":"single","prompt":"Une GPO contient uniquement des paramètres « Configuration ordinateur » et elle est liée à une OU qui ne contient que des comptes utilisateurs. Que se passe-t-il ?","choices":[{"id":"a","text":"Les paramètres s’appliquent à tout le domaine"},{"id":"b","text":"La GPO est automatiquement déplacée vers la bonne OU"},{"id":"c","text":"Les paramètres s’appliquent aux postes sur lesquels ces utilisateurs se connectent"},{"id":"d","text":"Rien : les paramètres ordinateur s’appliquent aux comptes ordinateurs présents dans l’OU, et il n’y en a pas"}],"answer":["d"],"explanation":"Une GPO s’applique aux objets de l’OU où elle est liée : la partie ordinateur aux ordinateurs, la partie utilisateur aux utilisateurs. Pour qu’un réglage ordinateur suive l’utilisateur, il faut un autre mécanisme (traitement en boucle de rappel), pas un changement d’OU automatique.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"f32802e6-83a1-5a34-bec8-0d45c50699bb","type":"single","prompt":"Pourquoi ne pas utiliser un compte administrateur du domaine pour lire ses courriels et naviguer sur Internet ?","choices":[{"id":"a","text":"Parce que les administrateurs n’ont pas accès à Internet"},{"id":"b","text":"Parce qu’un logiciel malveillant exécuté dans cette session hériterait des droits sur tout le domaine ; on sépare compte d’administration et compte courant"},{"id":"c","text":"Parce que cela consomme plus de licences"},{"id":"d","text":"Parce que la messagerie refuse les administrateurs"}],"answer":["b"],"explanation":"Les tâches courantes exposent à l’hameçonnage et aux sites piégés. Un compte dédié à l’administration, utilisé seulement depuis des postes d’administration, limite ce qu’une compromission de la session courante permet.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"d4cca4b4-e5c7-5fb8-b415-28e8905415d6","type":"single","prompt":"Quelle est la méthode recommandée pour donner aux membres de l’équipe RH l’accès en modification au partage « RH » ?","choices":[{"id":"a","text":"Rendre les utilisateurs administrateurs du serveur de fichiers"},{"id":"b","text":"Mettre les comptes dans un groupe global, imbriqué dans un groupe de domaine local qui reçoit les droits NTFS sur le dossier"},{"id":"c","text":"Donner « Contrôle total » à « Tout le monde » et se fier au nom du partage"},{"id":"d","text":"Ajouter chaque compte individuellement dans les droits NTFS"}],"answer":["b"],"explanation":"Le modèle AGDLP sépare qui (groupe global des RH) de ce qui est permis (groupe de domaine local sur la ressource). Arrivées et départs se gèrent dans un groupe, sans retoucher les droits du dossier. Les droits individuels deviennent vite ingérables, et les autres options sont dangereuses.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"62e98c29-cb2c-548b-93de-b4656a8e7db0","type":"single","prompt":"Un dossier partagé a des autorisations de partage « Lecture » et des autorisations NTFS « Modification » pour le même groupe. Que peut faire un membre de ce groupe depuis le réseau ?","choices":[{"id":"a","text":"Rien : les deux s’annulent"},{"id":"b","text":"Contrôle total : les deux s’additionnent"},{"id":"c","text":"Modifier : NTFS l’emporte toujours"},{"id":"d","text":"Seulement lire : la permission effective est la plus restrictive des deux"}],"answer":["d"],"explanation":"Depuis le réseau, on combine le partage et NTFS en gardant le plus restrictif. Une pratique courante consiste à ouvrir largement le partage (aux utilisateurs authentifiés) et à régler finement les droits NTFS.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"b1ce2bec-101a-52e1-b41c-c7b7a99e072d","type":"single","prompt":"Un utilisateur a supprimé un compte de service dans Active Directory par erreur. Quelle fonction permet de le restaurer avec ses attributs et appartenances aux groupes, si elle a été activée ?","choices":[{"id":"a","text":"La Corbeille Active Directory"},{"id":"b","text":"gpupdate /force"},{"id":"c","text":"La recréation d’un compte portant le même nom"},{"id":"d","text":"La Corbeille du bureau du contrôleur de domaine"}],"answer":["a"],"explanation":"La Corbeille AD conserve l’objet supprimé avec tous ses attributs pendant sa durée de vie. Un compte recréé avec le même nom a un nouvel identifiant (SID) : il ne retrouve ni ses droits ni ses appartenances.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"8310b163-d37f-53b6-a628-fececc0b7197","type":"single","prompt":"Le contrôleur de domaine qui détenait le rôle d’émulateur PDC est définitivement perdu. Que faire ?","choices":[{"id":"a","text":"Saisir (seize) le rôle sur un autre contrôleur de domaine sain, puis nettoyer les métadonnées de l’ancien et ne jamais le remettre en ligne"},{"id":"b","text":"Réinstaller Windows sur un serveur avec le même nom et la même adresse IP"},{"id":"c","text":"Attendre que les postes désignent un nouveau détenteur automatiquement"},{"id":"d","text":"Transférer le rôle depuis l’ancien contrôleur"}],"answer":["a"],"explanation":"Un transfert nécessite que l’ancien détenteur réponde ; s’il est perdu, on saisit le rôle avec ntdsutil ou Move-ADDirectoryServerOperationMasterRole -Force. Les rôles FSMO ne se réattribuent pas tout seuls. Remettre en ligne l’ancien serveur créerait deux détenteurs.","difficulty":"expert","platform":"windows"}$q$::jsonb),
    ($q${"id":"dd706568-1b2c-5715-a45f-934ac6b30a6d","type":"single","prompt":"Comment vérifier que la réplication entre contrôleurs de domaine fonctionne ?","choices":[{"id":"a","text":"sfc /scannow"},{"id":"b","text":"ipconfig /registerdns"},{"id":"c","text":"gpresult /r"},{"id":"d","text":"repadmin /replsummary (et /showrepl)"}],"answer":["d"],"explanation":"repadmin résume les dernières réplications, les échecs et leurs erreurs par partenaire. dcdiag complète le diagnostic. Les autres commandes concernent l’enregistrement DNS d’un poste, les GPO et les fichiers système.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"08493534-4ef8-52bd-aaa7-ca0e154dd5ff","type":"single","prompt":"Pourquoi faut-il au moins deux contrôleurs de domaine dans un domaine de production ?","choices":[{"id":"a","text":"Pour séparer les utilisateurs et les ordinateurs"},{"id":"b","text":"Pour que l’authentification, le DNS intégré et les GPO restent disponibles si l’un tombe ou pendant sa maintenance"},{"id":"c","text":"Pour doubler la taille maximale de l’annuaire"},{"id":"d","text":"Parce qu’Active Directory refuse de démarrer avec un seul contrôleur"}],"answer":["b"],"explanation":"Les contrôleurs répliquent l’annuaire entre eux : la perte de l’un ne bloque pas le domaine. Un seul contrôleur fonctionne, mais sa panne arrête les ouvertures de session et, sans sauvegarde, tout l’annuaire est perdu.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"b788f411-f7a1-51b7-a9c8-ca3ac5768293","type":"single","prompt":"Qu’est-ce qui distingue un point de contrôle (checkpoint) Hyper-V d’une sauvegarde ?","choices":[{"id":"a","text":"Aucune différence, c’est une sauvegarde complète"},{"id":"b","text":"Le point de contrôle est stocké automatiquement sur un autre site"},{"id":"c","text":"Le point de contrôle ne contient que la mémoire vive"},{"id":"d","text":"Le point de contrôle dépend des disques de la machine virtuelle et du même stockage : il sert à revenir en arrière après un essai, pas à se protéger d’une panne"}],"answer":["d"],"explanation":"Un point de contrôle enregistre les écritures dans des fichiers de différence à côté du disque d’origine. Si le stockage est perdu, tout disparaît ensemble. Les conserver longtemps dégrade aussi les performances. Une sauvegarde est une copie indépendante, stockée ailleurs.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"2b568957-fff3-5bad-be9c-907db8ab1370","type":"single","prompt":"Une machine virtuelle Hyper-V doit communiquer avec le réseau physique de l’entreprise. Quel type de commutateur virtuel utiliser ?","choices":[{"id":"a","text":"Interne"},{"id":"b","text":"Aucun commutateur"},{"id":"c","text":"Privé"},{"id":"d","text":"Externe"}],"answer":["d"],"explanation":"Un commutateur externe est relié à une carte physique de l’hôte. Un commutateur interne ne relie que les VM et l’hôte, et un privé seulement les VM entre elles.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"343617ea-11d6-5ba1-89e2-f92a0506d3c7","type":"single","prompt":"Comment exécuter la même commande PowerShell sur cinquante serveurs sans s’y connecter un par un ?","choices":[{"id":"a","text":"Avec ping"},{"id":"b","text":"En ouvrant cinquante sessions Bureau à distance"},{"id":"c","text":"Avec Invoke-Command -ComputerName et la gestion à distance (WinRM) activée"},{"id":"d","text":"En copiant le script sur chaque serveur par clé USB"}],"answer":["c"],"explanation":"PowerShell Remoting exécute un bloc de script sur plusieurs machines en parallèle et rapporte les résultats. On teste d’abord sur un serveur, avec -WhatIf quand la commande le permet, avant de l’étendre aux autres.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"1726a30e-73e5-5a9b-bbe6-65e5c11ecd0f","type":"single","prompt":"Que fait `Get-ADUser -Filter * -Properties LastLogonDate | Where-Object LastLogonDate -lt (Get-Date).AddDays(-90)` ?","choices":[{"id":"a","text":"Il réinitialise les mots de passe expirés"},{"id":"b","text":"Il liste les comptes utilisateurs dont la dernière connexion connue remonte à plus de 90 jours, sans rien modifier"},{"id":"c","text":"Il supprime les comptes inactifs depuis 90 jours"},{"id":"d","text":"Il désactive tous les comptes"}],"answer":["b"],"explanation":"Get- ne fait que lire. On examine la liste (comptes de service, absences longues) avant toute action ; la désactivation se ferait ensuite avec Disable-ADAccount, idéalement testée avec -WhatIf. Les comptes sans connexion ont une date vide et doivent être traités à part.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"f44b8d76-375c-5aa0-8404-873d8ce7f1e8","type":"multiple","prompt":"Cochez les mesures qui réduisent le risque sur les comptes administrateurs locaux des postes.","choices":[{"id":"a","text":"Le même mot de passe sur tous les postes pour faciliter le support"},{"id":"b","text":"Noter le mot de passe commun dans un fichier partagé"},{"id":"c","text":"Un mot de passe différent et renouvelé automatiquement sur chaque poste (Windows LAPS)"},{"id":"d","text":"Restreindre les connexions réseau de ces comptes"}],"answer":["c","d"],"explanation":"Un mot de passe administrateur local commun permet à un attaquant de passer d’un poste à tous les autres. LAPS génère un mot de passe unique par poste, stocké dans l’annuaire avec des droits de lecture contrôlés.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"e2be7f4a-e817-5cc5-acef-b469af15d32d","type":"single","prompt":"Un serveur DHCP Windows ne distribue plus d’adresses aux postes d’un nouveau VLAN, alors qu’il sert les autres. Quelle cause est la plus probable ?","choices":[{"id":"a","text":"L’absence de relais DHCP (adresse « ip helper ») sur le routeur de ce VLAN, ou d’étendue pour son réseau"},{"id":"b","text":"Le service DHCP est arrêté"},{"id":"c","text":"Les postes ont un antivirus"},{"id":"d","text":"Le DNS ne répond pas"}],"answer":["a"],"explanation":"Les requêtes DHCP sont des diffusions qui ne franchissent pas un routeur : il faut un relais vers le serveur, et une étendue correspondant au réseau du VLAN. Un service arrêté toucherait aussi les autres réseaux.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"c21c9294-2f5f-542d-9f27-9e94a1940555","type":"single","prompt":"Vous devez appliquer une mise à jour critique sur 200 serveurs Windows. Quelle démarche est la plus sûre ?","choices":[{"id":"a","text":"Attendre la prochaine panne pour la déployer"},{"id":"b","text":"Tout déployer en même temps pour gagner du temps"},{"id":"c","text":"Déployer d’abord sur un groupe de test, vérifier, puis étendre par vagues avec un plan de retour arrière"},{"id":"d","text":"Désactiver les mises à jour automatiques et ne rien faire"}],"answer":["c"],"explanation":"Le déploiement par vagues (WSUS, Configuration Manager, Azure Update Manager) limite l’impact d’une mise à jour défectueuse. Tout déployer d’un coup risque un arrêt général ; ne rien faire laisse la faille ouverte.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"98ea9d82-1809-5c53-8a0a-946b0a9d1659","type":"single","prompt":"Que garantit une sauvegarde « état du système » d’un contrôleur de domaine ?","choices":[{"id":"a","text":"Une copie de la messagerie"},{"id":"b","text":"La sauvegarde des documents de tous les utilisateurs du domaine"},{"id":"c","text":"La possibilité de restaurer l’annuaire Active Directory (base NTDS, SYSVOL, Registre) de ce contrôleur"},{"id":"d","text":"La sauvegarde de tous les serveurs membres"}],"answer":["c"],"explanation":"L’état du système contient ce qu’il faut pour restaurer le rôle du contrôleur. Les fichiers des utilisateurs et les autres serveurs ont leurs propres sauvegardes. Une restauration d’annuaire se teste régulièrement, sur un environnement isolé.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"ffb3f849-f214-5c37-86d6-00d8194ff357","type":"single","prompt":"Après une restauration d’un contrôleur de domaine depuis une vieille image de machine virtuelle, la réplication est bloquée et les journaux signalent un retour en arrière de l’USN. Quelle est la bonne conclusion ?","choices":[{"id":"a","text":"C’est sans conséquence, la réplication reprendra seule"},{"id":"b","text":"Il faut forcer la réplication depuis ce contrôleur vers tous les autres"},{"id":"c","text":"Ce contrôleur ne doit pas rester en service : on le retire, on nettoie ses métadonnées et on le reconstruit à partir des autres contrôleurs"},{"id":"d","text":"Il suffit de redémarrer le service DNS"}],"answer":["c"],"explanation":"Restaurer une image remet en arrière ses compteurs de réplication : les autres contrôleurs ignorent ses modifications et l’annuaire diverge. On ne force pas sa version sur les autres. On le reconstruit, et on sauvegarde les contrôleurs par l’état du système, pas par des images.","difficulty":"expert","platform":"windows"}$q$::jsonb),
    ($q${"id":"c8a9774c-e467-57e8-870c-dd8f30b41f59","type":"single","prompt":"Pourquoi préférer Windows Server en mode Core (sans interface graphique) pour un contrôleur de domaine ?","choices":[{"id":"a","text":"Parce qu’il ne nécessite aucune administration"},{"id":"b","text":"Parce qu’il est le seul à pouvoir porter Active Directory"},{"id":"c","text":"Parce qu’il est gratuit"},{"id":"d","text":"Moins de composants installés : moins de mises à jour, moins de redémarrages et une surface d’attaque réduite"}],"answer":["d"],"explanation":"Le mode Core retire l’interface graphique et de nombreux composants. Il s’administre à distance (PowerShell, outils RSAT, Windows Admin Center). Les deux modes peuvent porter Active Directory et ont la même licence.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"adc539c0-7711-5c90-a4b0-b5434cb35dd1","type":"multiple","prompt":"Un compte administrateur du domaine est suspecté d’être compromis. Cochez les actions appropriées.","choices":[{"id":"a","text":"Supprimer les journaux de sécurité pour repartir proprement"},{"id":"b","text":"Attendre une seconde alerte avant d’agir"},{"id":"c","text":"Réinitialiser son mot de passe et révoquer ses sessions, puis examiner les journaux de sécurité des contrôleurs (créations de comptes, ajouts à des groupes privilégiés)"},{"id":"d","text":"Vérifier les membres des groupes Admins du domaine et Administrateurs de l’entreprise"}],"answer":["c","d"],"explanation":"On coupe l’accès, puis on recherche ce que l’attaquant a pu installer pour revenir (nouveaux comptes, appartenances, GPO modifiées). Effacer les journaux détruit les preuves ; attendre lui laisse le temps de s’installer. Une compromission profonde peut aussi exiger de renouveler deux fois le mot de passe du compte krbtgt.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"ca38d0a6-f8ec-5780-a231-4d161be32c7f","type":"single","prompt":"À quoi sert une unité d’organisation (OU) dans Active Directory ?","choices":[{"id":"a","text":"À organiser les objets pour leur lier des GPO et déléguer leur administration"},{"id":"b","text":"À séparer deux forêts"},{"id":"c","text":"À regrouper des utilisateurs pour leur envoyer des courriels"},{"id":"d","text":"À donner des droits d’accès aux fichiers"}],"answer":["a"],"explanation":"Une OU est un conteneur d’administration : on y lie des stratégies et on délègue, par exemple, la réinitialisation des mots de passe d’un service à son responsable. Les droits sur les fichiers se donnent à des groupes, pas à des OU.","difficulty":"advanced","platform":"windows"}$q$::jsonb),
    ($q${"id":"ea6189f1-ac2f-5357-bd20-62a083de1cf6","type":"single","prompt":"Pourquoi exécuter les tests automatiquement sur chaque demande de fusion (pull request) plutôt qu’après la fusion ?","choices":[{"id":"a","text":"Pour que les tests s’exécutent plus vite"},{"id":"b","text":"Pour détecter un problème avant qu’il n’atteigne la branche principale, quand il est encore simple à attribuer et à corriger"},{"id":"c","text":"Pour éviter d’écrire des tests unitaires"},{"id":"d","text":"Parce qu’on ne peut pas tester après une fusion"}],"answer":["b"],"explanation":"L’intégration continue protège la branche principale : une modification qui casse quelque chose est refusée avant de gêner les autres. Après la fusion, il faut retrouver la cause parmi plusieurs changements.","difficulty":"intermediate","platform":"devops"}$q$::jsonb),
    ($q${"id":"9a55f0ec-ae29-5b3b-b517-499b61a2c416","type":"single","prompt":"Un test échoue une fois sur dix dans la CI, sans changement de code. Quelle réponse est la bonne ?","choices":[{"id":"a","text":"Relancer la CI jusqu’à ce qu’elle passe"},{"id":"b","text":"Chercher la cause (dépendance à l’ordre, à l’heure, à un délai, à un état partagé) et la corriger"},{"id":"c","text":"Augmenter tous les délais d’attente à dix minutes"},{"id":"d","text":"Le désactiver définitivement"}],"answer":["b"],"explanation":"Un test instable signale souvent un vrai défaut (course, dépendance cachée) ou un test mal conçu. Le relancer en boucle habitue l’équipe à ignorer le rouge, et le désactiver retire une protection. On le corrige, ou on le met en quarantaine visible avec un suivi.","difficulty":"intermediate","platform":"devops"}$q$::jsonb),
    ($q${"id":"61b5fc5d-0d73-5762-bbb8-fe1e3b22c1b1","type":"single","prompt":"Où ranger le jeton de déploiement utilisé par un pipeline CI ?","choices":[{"id":"a","text":"En clair dans le fichier du pipeline, dans le dépôt"},{"id":"b","text":"Dans le README pour que l’équipe le retrouve"},{"id":"c","text":"Dans une variable affichée dans les journaux pour faciliter le débogage"},{"id":"d","text":"Dans le gestionnaire de secrets de la CI (ou un coffre-fort), injecté au moment de l’exécution, avec les droits minimaux"}],"answer":["d"],"explanation":"Tout ce qui est dans le dépôt est lisible par quiconque y a accès, y compris dans l’historique. Les secrets de la CI sont masqués dans les journaux. On limite aussi le jeton à ce dont le pipeline a besoin, et on préfère quand c’est possible une fédération d’identité (OIDC) sans secret longue durée.","difficulty":"intermediate","platform":"devops"}$q$::jsonb),
    ($q${"id":"0f46faf3-59fc-5454-889c-9f0bc568421c","type":"single","prompt":"Pourquoi construire l’artefact (image, paquet) une seule fois, puis promouvoir ce même artefact de la recette à la production ?","choices":[{"id":"a","text":"Pour que ce qui a été testé soit exactement ce qui est déployé ; reconstruire peut produire un résultat différent"},{"id":"b","text":"Pour économiser l’espace disque du registre"},{"id":"c","text":"Parce que la production ne sait pas construire"},{"id":"d","text":"Pour éviter de versionner le code"}],"answer":["a"],"explanation":"Une reconstruction peut tirer d’autres versions de dépendances ou d’image de base. On identifie l’artefact par sa version ou son condensat et on le fait avancer d’environnement en environnement, seule la configuration change.","difficulty":"intermediate","platform":"devops"}$q$::jsonb),
    ($q${"id":"b3fada5f-1bd9-5e83-9f1f-239953186fb2","type":"single","prompt":"Qu’est-ce qu’un déploiement canari ?","choices":[{"id":"a","text":"Tester la version uniquement sur le poste du développeur"},{"id":"b","text":"Envoyer d’abord une petite part du trafic vers la nouvelle version, observer ses indicateurs, puis élargir ou revenir en arrière"},{"id":"c","text":"Déployer sur tous les serveurs en même temps"},{"id":"d","text":"Déployer uniquement la nuit"}],"answer":["b"],"explanation":"Le canari limite l’exposition : si le taux d’erreur ou la latence se dégradent, peu d’utilisateurs sont touchés et on revient en arrière. Il suppose des indicateurs fiables et un critère de décision fixé à l’avance.","difficulty":"advanced","platform":"devops"}$q$::jsonb),
    ($q${"id":"67685924-ef0d-5e59-8d28-1cde49eca26a","type":"single","prompt":"Une migration de base de données doit accompagner une nouvelle version, et on veut pouvoir revenir à l’ancienne version de l’application. Quelle stratégie suivre ?","choices":[{"id":"a","text":"Arrêter le service le temps de tout réécrire"},{"id":"b","text":"Ne jamais modifier le schéma"},{"id":"c","text":"Supprimer l’ancienne colonne dans la même livraison"},{"id":"d","text":"Des changements compatibles avec les deux versions (ajouter une colonne d’abord, supprimer l’ancienne dans une livraison ultérieure)"}],"answer":["d"],"explanation":"Le schéma « étendre puis contracter » permet à l’ancienne et à la nouvelle version de fonctionner sur la même base. Supprimer tout de suite rend le retour arrière impossible sans restauration de données.","difficulty":"advanced","platform":"devops"}$q$::jsonb),
    ($q${"id":"bd0aa4f2-de64-5303-bbcb-67be8f5f9b85","type":"single","prompt":"Que contient le fichier d’état (state) de Terraform, et pourquoi le stocker dans un backend distant verrouillé ?","choices":[{"id":"a","text":"Le code source de Terraform ; on le stocke à distance pour le partager"},{"id":"b","text":"Rien d’important, il peut être supprimé à tout moment"},{"id":"c","text":"La correspondance entre la configuration et les ressources réelles ; un backend distant verrouillé évite que deux personnes l’écrivent en même temps et le protège"},{"id":"d","text":"Uniquement les mots de passe ; on le stocke à distance pour les cacher"}],"answer":["c"],"explanation":"Sans état, Terraform ne sait plus quelles ressources il gère. Deux exécutions simultanées sur un même fichier local peuvent le corrompre. L’état peut aussi contenir des valeurs sensibles : son stockage est chiffré et son accès restreint.","difficulty":"intermediate","platform":"devops"}$q$::jsonb),
    ($q${"id":"19f48c74-28a1-5517-a1ee-c66ea02c53d1","type":"single","prompt":"Pourquoi lire attentivement la sortie de `terraform plan` avant `apply` ?","choices":[{"id":"a","text":"Parce que plan corrige automatiquement les erreurs"},{"id":"b","text":"Ce n’est pas utile, apply redemande toujours confirmation pour chaque ressource"},{"id":"c","text":"Parce qu’elle indique ce qui sera créé, modifié ou détruit ; un « must be replaced » sur une base de données signifie sa recréation"},{"id":"d","text":"Parce que plan applique déjà la moitié des changements"}],"answer":["c"],"explanation":"Certains changements d’attribut imposent la destruction puis la recréation d’une ressource. Le plan le dit explicitement. On l’enregistre (plan -out) et on applique exactement ce plan relu.","difficulty":"intermediate","platform":"devops"}$q$::jsonb),
    ($q${"id":"ccb6b61e-4c16-5a1c-a3b5-3a17b6e78a72","type":"single","prompt":"Quelqu’un a modifié à la main, dans la console du fournisseur, une règle de pare-feu gérée par Terraform. Que se passe-t-il au prochain plan ?","choices":[{"id":"a","text":"Terraform adopte la modification manuelle et met à jour le code"},{"id":"b","text":"Terraform ignore la modification pour toujours"},{"id":"c","text":"Terraform détecte l’écart (drift) et propose de remettre la ressource dans l’état décrit par le code"},{"id":"d","text":"Terraform supprime le compte de la personne"}],"answer":["c"],"explanation":"Le code est la référence : le plan compare l’état réel à la configuration et propose de corriger l’écart. Si la modification manuelle était voulue, on la reporte dans le code ; sinon l’apply l’annule. D’où l’intérêt de restreindre les modifications manuelles.","difficulty":"advanced","platform":"devops"}$q$::jsonb),
    ($q${"id":"9a54f52f-efb8-503a-8da4-572920ec98ac","type":"single","prompt":"Comment protéger une base de données gérée par Terraform contre une destruction accidentelle ?","choices":[{"id":"a","text":"En lui donnant un nom difficile à retenir"},{"id":"b","text":"En ne lançant jamais terraform plan"},{"id":"c","text":"En la retirant du contrôle de version"},{"id":"d","text":"Avec lifecycle { prevent_destroy = true }, en plus de la protection contre la suppression du fournisseur et de sauvegardes"}],"answer":["d"],"explanation":"prevent_destroy fait échouer tout plan qui détruirait la ressource. La protection du fournisseur (deletion protection) ajoute un second verrou indépendant de Terraform, et les sauvegardes restent la dernière ligne de défense.","difficulty":"advanced","platform":"devops"}$q$::jsonb),
    ($q${"id":"37a65a5d-7e3a-5b2d-977a-cb3ab5eac1d5","type":"multiple","prompt":"Cochez les trois piliers classiques de l’observabilité.","choices":[{"id":"a","text":"Les traces distribuées"},{"id":"b","text":"Le nombre de lignes de code"},{"id":"c","text":"Les métriques"},{"id":"d","text":"Les journaux (logs)"}],"answer":["a","c","d"],"explanation":"Les métriques disent qu’il se passe quelque chose et dans quelle mesure, les journaux disent ce qui s’est passé à un endroit, les traces suivent une requête à travers plusieurs services. Le nombre de lignes de code ne renseigne pas sur le comportement en production.","difficulty":"intermediate","platform":"devops"}$q$::jsonb),
    ($q${"id":"e6ccc17a-f1d4-5e58-a20e-cbba583035de","type":"single","prompt":"Pourquoi alerter sur les symptômes vus par les utilisateurs (taux d’erreur, latence) plutôt que sur chaque cause possible (CPU à 80 %) ?","choices":[{"id":"a","text":"Pour avoir moins de tableaux de bord"},{"id":"b","text":"Parce que les métriques de CPU sont toujours fausses"},{"id":"c","text":"Parce qu’il est interdit de mesurer le CPU"},{"id":"d","text":"Parce qu’une alerte doit appeler une action : un CPU élevé sans impact réveille l’astreinte pour rien, alors qu’un taux d’erreur en hausse touche réellement les utilisateurs"}],"answer":["d"],"explanation":"Trop d’alertes sans conséquence usent l’astreinte, qui finit par les ignorer. Les causes restent visibles dans les tableaux de bord pour le diagnostic ; les alertes se concentrent sur ce qui dégrade le service.","difficulty":"advanced","platform":"devops"}$q$::jsonb),
    ($q${"id":"8b96f929-c9d8-5018-8101-9dc2eec976dd","type":"single","prompt":"Un SLO de disponibilité est fixé à 99,9 % sur 30 jours. Que représente le budget d’erreur ?","choices":[{"id":"a","text":"Le nombre de bugs autorisés dans le code"},{"id":"b","text":"Le coût des serveurs de secours"},{"id":"c","text":"Le temps de réponse maximal d’une requête"},{"id":"d","text":"Environ 43 minutes d’indisponibilité tolérées sur la période ; tant qu’il en reste, on peut livrer, sinon on priorise la fiabilité"}],"answer":["d"],"explanation":"0,1 % de 30 jours fait environ 43 minutes. Le budget d’erreur arbitre entre vitesse de livraison et fiabilité de façon objective : quand il est consommé, l’équipe ralentit les changements risqués.","difficulty":"advanced","platform":"devops"}$q$::jsonb),
    ($q${"id":"4d30d4b5-d472-5395-8d61-4255ea5203b8","type":"single","prompt":"À quoi sert une analyse post-incident « sans reproche » (blameless) ?","choices":[{"id":"a","text":"À éviter de documenter les incidents"},{"id":"b","text":"À clore l’incident le plus vite possible"},{"id":"c","text":"À identifier la personne responsable pour la sanctionner"},{"id":"d","text":"À comprendre comment le système a permis l’incident et à le rendre plus robuste, en obtenant des faits honnêtes plutôt que des justifications"}],"answer":["d"],"explanation":"Si une erreur humaine a suffi à provoquer l’incident, c’est que le système manquait de garde-fous. Une analyse qui cherche un coupable pousse à cacher les faits, et les mêmes faiblesses restent en place.","difficulty":"intermediate","platform":"devops"}$q$::jsonb),
    ($q${"id":"ec779752-7c5b-5916-80f4-bf571246bc35","type":"single","prompt":"Un pod est en état `CrashLoopBackOff`. Quelles commandes donnent en premier la raison ?","choices":[{"id":"a","text":"`kubectl get nodes`"},{"id":"b","text":"`kubectl scale --replicas=0`"},{"id":"c","text":"`kubectl delete pod <pod>` puis attendre"},{"id":"d","text":"`kubectl describe pod <pod>` (événements, code de sortie) et `kubectl logs <pod> --previous` (sortie du conteneur qui a planté)"}],"answer":["d"],"explanation":"Le conteneur démarre puis s’arrête en boucle : ses journaux du lancement précédent et les événements du pod (OOMKilled, sonde en échec, erreur de configuration) indiquent pourquoi. Supprimer le pod en recrée un identique qui plantera de la même façon.","difficulty":"intermediate","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"a045157e-27b9-5970-8b39-87ce2d1d1285","type":"single","prompt":"Un pod reste en `ImagePullBackOff`. Quelles causes vérifier ?","choices":[{"id":"a","text":"Une variable d’environnement manquante dans l’application"},{"id":"b","text":"Le nom ou l’étiquette de l’image, et les droits d’accès au registre privé (imagePullSecrets)"},{"id":"c","text":"Une sonde de vivacité mal réglée"},{"id":"d","text":"Le manque de mémoire du conteneur"}],"answer":["b"],"explanation":"Le nœud n’arrive pas à télécharger l’image : faute de frappe, étiquette inexistante ou authentification manquante. kubectl describe pod affiche le message du registre. Les problèmes de mémoire ou de configuration interviennent après le démarrage du conteneur.","difficulty":"intermediate","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"98d72dff-ee81-5650-96bb-f3ee48f8362f","type":"single","prompt":"Quelle différence entre une sonde de vivacité (liveness) et une sonde de disponibilité (readiness) ?","choices":[{"id":"a","text":"Ce sont deux noms pour la même chose"},{"id":"b","text":"La readiness redémarre le pod, la liveness le retire du Service"},{"id":"c","text":"La liveness ne sert qu’au démarrage"},{"id":"d","text":"Une liveness en échec fait redémarrer le conteneur ; une readiness en échec le retire seulement des points d’accès du Service, sans le redémarrer"}],"answer":["d"],"explanation":"La readiness dit « je ne peux pas recevoir de trafic pour l’instant » (démarrage, dépendance indisponible). La liveness dit « je suis bloqué, redémarrez-moi ». Une liveness qui teste une dépendance externe peut faire redémarrer tous les pods en cascade lors d’une panne de cette dépendance.","difficulty":"intermediate","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"3afae9a7-9365-50fd-b79a-dea5f3247d62","type":"single","prompt":"Un Service ne transmet aucun trafic à ses pods, qui tournent pourtant et sont prêts. Que vérifier en premier ?","choices":[{"id":"a","text":"Que le sélecteur du Service correspond bien aux étiquettes des pods (kubectl get endpoints montre une liste vide sinon)"},{"id":"b","text":"La version de Kubernetes"},{"id":"c","text":"La taille des images"},{"id":"d","text":"Le nombre de nœuds du cluster"}],"answer":["a"],"explanation":"Un Service choisit ses pods par étiquettes. Une faute dans le sélecteur ou dans les étiquettes du Deployment laisse les points d’accès vides : le Service existe mais ne renvoie vers rien. On vérifie aussi que targetPort correspond au port réellement écouté.","difficulty":"advanced","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"405b5fa3-b576-5e99-bac8-c817dadc5d3c","type":"single","prompt":"Pourquoi définir des requests et des limits de ressources sur les conteneurs ?","choices":[{"id":"a","text":"Pour que les pods démarrent plus vite"},{"id":"b","text":"Parce que Kubernetes refuse les pods sans limits"},{"id":"c","text":"Pour chiffrer la mémoire des conteneurs"},{"id":"d","text":"Les requests servent au placement des pods sur les nœuds ; les limits empêchent un conteneur de consommer les ressources des autres"}],"answer":["d"],"explanation":"Sans requests, l’ordonnanceur entasse des pods sur un nœud qui ne peut pas les porter. Sans limits mémoire, un conteneur qui fuit peut épuiser le nœud. Une limite mémoire dépassée provoque un OOMKilled ; une limite CPU dépassée, un ralentissement.","difficulty":"intermediate","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"f2ddcf0f-97c8-5055-801b-013756242807","type":"single","prompt":"Les Secrets Kubernetes sont-ils chiffrés par défaut ?","choices":[{"id":"a","text":"Oui, Kubernetes les stocke hors du cluster"},{"id":"b","text":"Ils ne sont jamais stockés"},{"id":"c","text":"Oui, avec une clé propre à chaque pod"},{"id":"d","text":"Non : ils sont seulement encodés en base64 ; il faut activer le chiffrement au repos dans etcd et restreindre leur lecture par RBAC"}],"answer":["d"],"explanation":"base64 n’est pas un chiffrement : quiconque lit l’objet lit le secret. On chiffre etcd, on limite qui peut faire get sur les Secrets et on envisage un gestionnaire externe (Vault, gestionnaire du fournisseur).","difficulty":"advanced","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"2d3d4a23-50d4-5750-8005-21fcd6dfd335","type":"single","prompt":"Comment revenir à la version précédente d’un Deployment après une mise à jour qui pose problème ?","choices":[{"id":"a","text":"Supprimer le namespace"},{"id":"b","text":"Supprimer le Deployment et le recréer à la main"},{"id":"c","text":"`kubectl rollout undo deployment/<nom>`, puis suivre `kubectl rollout status`"},{"id":"d","text":"Redémarrer tous les nœuds"}],"answer":["c"],"explanation":"Le Deployment garde l’historique de ses ReplicaSets et peut revenir au précédent par une mise à jour progressive. Dans une démarche GitOps, on revient plutôt en arrière dans le dépôt, pour que le cluster et le code restent alignés.","difficulty":"intermediate","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"7a6a28c1-ba55-55aa-be75-e9b4e80363d9","type":"single","prompt":"Que garantit un PodDisruptionBudget (`minAvailable: 2`) pendant la maintenance d’un nœud ?","choices":[{"id":"a","text":"Que les évictions volontaires (drain) ne descendront pas sous 2 pods disponibles de l’application"},{"id":"b","text":"Que l’application ne tombera jamais en panne"},{"id":"c","text":"Que les pods ne consomment pas plus de deux cœurs"},{"id":"d","text":"Que deux nœuds restent toujours allumés"}],"answer":["a"],"explanation":"Le PDB freine les interruptions planifiées : kubectl drain attend que d’autres pods soient prêts avant d’en évincer davantage. Il ne protège pas d’une panne soudaine d’un nœud, d’où l’intérêt de répartir les réplicas sur plusieurs nœuds.","difficulty":"advanced","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"5973ab83-a1f5-5f1b-9af5-1a3999ee6d6a","type":"single","prompt":"Une NetworkPolicy « deny all » en entrée est appliquée à un namespace. Que se passe-t-il pour les pods de ce namespace ?","choices":[{"id":"a","text":"Ils ne peuvent plus rien envoyer vers l’extérieur"},{"id":"b","text":"Ils ne reçoivent plus aucun trafic entrant, sauf celui autorisé explicitement par d’autres NetworkPolicies (si le plugin réseau les applique)"},{"id":"c","text":"Rien : les NetworkPolicies ne sont que de la documentation"},{"id":"d","text":"Ils sont supprimés"}],"answer":["b"],"explanation":"Les NetworkPolicies sont additives : un refus par défaut, puis des autorisations précises par étiquette et par port. Elles n’ont d’effet que si le plugin réseau du cluster les applique (Calico, Cilium…). Une politique d’entrée ne restreint pas la sortie.","difficulty":"advanced","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"63743262-ec4e-5285-8f8e-77c28b4639ce","type":"multiple","prompt":"Cochez les bonnes pratiques de sécurité pour les pods d’une application.","choices":[{"id":"a","text":"Donner au compte de service du pod uniquement les droits RBAC nécessaires"},{"id":"b","text":"Utiliser le compte de service par défaut avec le rôle cluster-admin"},{"id":"c","text":"Faire tourner les conteneurs avec un utilisateur non root (runAsNonRoot) et sans élévation de privilèges"},{"id":"d","text":"Lancer les pods en privileged pour éviter les erreurs"}],"answer":["a","c"],"explanation":"Moins de privilèges dans le conteneur et dans l’API limitent ce qu’un attaquant peut faire depuis un pod compromis. Un pod privilégié ou lié à cluster-admin donne la main sur le nœud ou sur tout le cluster.","difficulty":"advanced","platform":"kubernetes"}$q$::jsonb),
    ($q${"id":"299bb669-de7a-5da7-bbaa-45710089b504","type":"single","prompt":"Une requête est lente. Quelle commande montre le plan réellement exécuté, avec les temps et le nombre de lignes de chaque étape ?","choices":[{"id":"a","text":"SHOW ALL"},{"id":"b","text":"VACUUM FULL"},{"id":"c","text":"EXPLAIN <requête> seul"},{"id":"d","text":"EXPLAIN (ANALYZE, BUFFERS) <requête>"}],"answer":["d"],"explanation":"EXPLAIN seul affiche le plan prévu et des estimations ; ANALYZE exécute vraiment la requête et donne les temps et lignes réels, BUFFERS les lectures en cache ou sur disque. Attention : ANALYZE exécute aussi un UPDATE ou un DELETE, à encadrer par BEGIN … ROLLBACK.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"955a4b46-716c-5d54-ab47-69ef908fbf1b","type":"single","prompt":"Dans un plan, une étape estime 10 lignes et en trouve 2 millions. Quelle est la piste la plus probable ?","choices":[{"id":"a","text":"Un mot de passe expiré"},{"id":"b","text":"Un nombre de connexions trop élevé"},{"id":"c","text":"Un disque trop lent"},{"id":"d","text":"Des statistiques obsolètes ou insuffisantes sur la table : lancer ANALYZE et, si besoin, augmenter la cible de statistiques de la colonne"}],"answer":["d"],"explanation":"Le planificateur choisit ses jointures et ses index d’après des estimations. Une erreur de cette ampleur conduit à un mauvais plan (boucle imbriquée sur des millions de lignes, par exemple). On rafraîchit les statistiques avant de chercher ailleurs.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"8bc0660a-88ed-5fe6-9772-4905e921c373","type":"single","prompt":"Pourquoi PostgreSQL a-t-il besoin de VACUUM ?","choices":[{"id":"a","text":"Pour créer les index manquants"},{"id":"b","text":"Parce qu’un UPDATE ou un DELETE laisse d’anciennes versions de lignes (MVCC) qu’il faut récupérer, et pour éviter le rebouclage des identifiants de transaction"},{"id":"c","text":"Pour compresser les sauvegardes"},{"id":"d","text":"Pour chiffrer les tables"}],"answer":["b"],"explanation":"Chaque modification crée une nouvelle version de ligne ; les anciennes restent jusqu’à ce que VACUUM les déclare réutilisables. Il gèle aussi les vieilles lignes pour éviter le rebouclage des identifiants de transaction, qui forcerait l’arrêt de la base. L’autovacuum s’en charge en temps normal.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"a8a94b45-8194-5dad-86e6-2efe48a39f83","type":"single","prompt":"Une table très modifiée grossit sans cesse malgré l’autovacuum. Quelle cause fréquente rechercher ?","choices":[{"id":"a","text":"Un manque de connexions"},{"id":"b","text":"Un index trop petit"},{"id":"c","text":"Une transaction restée ouverte longtemps (souvent « idle in transaction ») qui empêche VACUUM de récupérer les lignes mortes"},{"id":"d","text":"Une mauvaise langue de collation"}],"answer":["c"],"explanation":"VACUUM ne peut pas supprimer une version de ligne qu’une transaction en cours pourrait encore voir. pg_stat_activity montre les transactions anciennes (xact_start) ; idle_in_transaction_session_timeout limite le problème côté serveur. Les slots de réplication abandonnés ont le même effet.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"d73844a9-299f-5f9d-a803-9da3603fda79","type":"single","prompt":"Pourquoi éviter `VACUUM FULL` sur une table de production en pleine journée ?","choices":[{"id":"a","text":"Parce qu’il supprime les données"},{"id":"b","text":"Parce qu’il réécrit toute la table sous un verrou exclusif : lectures et écritures sont bloquées pendant l’opération"},{"id":"c","text":"Parce qu’il désactive l’autovacuum définitivement"},{"id":"d","text":"Parce qu’il ne libère jamais d’espace"}],"answer":["b"],"explanation":"VACUUM FULL rend l’espace au système en recopiant la table, ce qui exige un verrou ACCESS EXCLUSIVE et de l’espace disque supplémentaire. On le planifie, ou on utilise un outil de réorganisation en ligne comme pg_repack.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"a66c1f2f-5d42-5980-8e59-6daf87ee4c22","type":"single","prompt":"Une recherche `WHERE lower(email) = $1` ne profite pas de l’index sur `email`. Pourquoi ?","choices":[{"id":"a","text":"Il faut redémarrer PostgreSQL pour activer l’index"},{"id":"b","text":"La table est trop petite pour avoir un index"},{"id":"c","text":"L’index porte sur email, pas sur lower(email) : il faut un index sur l’expression lower(email)"},{"id":"d","text":"Les index ne fonctionnent jamais avec WHERE"}],"answer":["c"],"explanation":"Le planificateur ne peut utiliser un index que si la condition porte sur ce qui est indexé. CREATE INDEX ON users (lower(email)) rend la recherche indexable. Sur une très petite table, un parcours séquentiel peut aussi être simplement plus rapide.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"89b3ed6b-b11c-56c0-860a-f979aafa9543","type":"single","prompt":"Comment ajouter un index sur une grande table en production sans bloquer les écritures ?","choices":[{"id":"a","text":"CREATE INDEX CONCURRENTLY, en vérifiant ensuite que l’index n’est pas resté invalide"},{"id":"b","text":"CREATE INDEX classique pendant les heures de pointe"},{"id":"c","text":"En arrêtant l’application"},{"id":"d","text":"En copiant la table dans une nouvelle table indexée"}],"answer":["a"],"explanation":"Un CREATE INDEX classique bloque les écritures pendant toute la construction. CONCURRENTLY est plus long mais laisse la table utilisable. S’il échoue, il laisse un index invalide (visible dans pg_index.indisvalid) à supprimer avant de recommencer. Il ne peut pas s’exécuter dans une transaction.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"cb7565f8-27d5-5ca1-93df-ed57a7028640","type":"single","prompt":"Quelle est la différence entre une sauvegarde logique (pg_dump) et une sauvegarde physique (pg_basebackup) ?","choices":[{"id":"a","text":"pg_basebackup n’exporte que le schéma"},{"id":"b","text":"Il n’y a aucune différence"},{"id":"c","text":"pg_dump est toujours plus rapide à restaurer sur une grosse base"},{"id":"d","text":"pg_dump exporte le contenu d’une base en SQL ou en archive ; pg_basebackup copie les fichiers de toute l’instance et permet, avec l’archivage des WAL, une restauration à un instant précis"}],"answer":["d"],"explanation":"La sauvegarde logique est portable entre versions et sélective (une base, une table). La sauvegarde physique restaure toute l’instance à l’identique et, combinée aux WAL archivés, à n’importe quel moment (PITR). Sur une très grosse base, une restauration logique est longue car elle reconstruit les index.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"c9f00f09-2734-5342-9a0e-432108d1e4ce","type":"single","prompt":"Un développeur a supprimé une table à 14 h 32. Vous disposez d’une sauvegarde physique de la nuit et des WAL archivés. Que faire ?","choices":[{"id":"a","text":"Rejouer les WAL jusqu’à maintenant"},{"id":"b","text":"Recréer la table vide"},{"id":"c","text":"Restaurer la sauvegarde de la nuit directement sur la production"},{"id":"d","text":"Restaurer la sauvegarde sur une autre instance avec recovery_target_time juste avant 14 h 32, puis récupérer la table et la réinjecter"}],"answer":["d"],"explanation":"La restauration à un instant précis (PITR) ramène l’instance juste avant l’erreur. On le fait à côté pour ne pas perdre les autres écritures intervenues depuis sur la production. Rejouer jusqu’à maintenant reproduirait la suppression.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"03eb5f13-2303-5d94-8b0a-5b2f5bf7b3f5","type":"single","prompt":"Une sauvegarde qui « réussit » chaque nuit est-elle une garantie suffisante ?","choices":[{"id":"a","text":"Non : seule une restauration testée régulièrement prouve qu’on peut récupérer les données, et en combien de temps"},{"id":"b","text":"Oui, si le fichier fait plus d’un gigaoctet"},{"id":"c","text":"Oui, si le code de retour est 0"},{"id":"d","text":"Oui, si elle est sur le même serveur"}],"answer":["a"],"explanation":"Une sauvegarde peut être incomplète, corrompue, ou impossible à restaurer faute d’outil ou de clé. On restaure régulièrement sur un environnement de test, on vérifie les données et on mesure la durée. Une copie sur le même serveur disparaît avec lui.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"1330c2e3-65f1-504e-b6d3-9aea5ffab38b","type":"single","prompt":"En réplication en flux (streaming) asynchrone, que risque-t-on lors d’une bascule après la perte du primaire ?","choices":[{"id":"a","text":"De perdre toute la base"},{"id":"b","text":"De perdre les dernières transactions validées sur le primaire mais pas encore reçues par le secondaire"},{"id":"c","text":"Rien, l’asynchrone garantit zéro perte"},{"id":"d","text":"Que le secondaire refuse de devenir primaire"}],"answer":["b"],"explanation":"En asynchrone, le primaire confirme la transaction sans attendre le secondaire : un retard de réplication devient une perte à la bascule. La réplication synchrone (synchronous_standby_names) évite cette perte au prix de la latence des écritures.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"6c124c1d-ba30-51af-82dc-1134b822b6d4","type":"single","prompt":"Comment surveiller le retard d’un secondaire en réplication ?","choices":[{"id":"a","text":"Avec ping entre les deux serveurs"},{"id":"b","text":"Avec pg_stat_replication sur le primaire (write_lag, flush_lag, replay_lag, écarts de LSN)"},{"id":"c","text":"Avec df -h sur le secondaire"},{"id":"d","text":"En comptant les lignes de chaque table"}],"answer":["b"],"explanation":"pg_stat_replication indique, pour chaque secondaire, la position reçue, écrite et rejouée et les délais correspondants. On alerte sur ces valeurs. Compter les lignes ne mesure rien de fiable et charge les deux serveurs.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"7a7e8a88-63b9-5f88-9ca3-0a9995935ca7","type":"single","prompt":"Le disque des WAL du primaire se remplit, et pg_replication_slots montre un slot inactif depuis trois jours. Que se passe-t-il ?","choices":[{"id":"a","text":"Le slot oblige le primaire à conserver tous les WAL que son consommateur n’a pas lus ; s’il est abandonné, on le supprime (après vérification), ou on borne avec max_slot_wal_keep_size"},{"id":"b","text":"Il faut supprimer les fichiers WAL à la main dans pg_wal"},{"id":"c","text":"Rien, les slots n’influencent pas les WAL"},{"id":"d","text":"Il faut augmenter max_connections"}],"answer":["a"],"explanation":"Un slot garantit que les WAL restent disponibles pour son consommateur, même absent. Supprimer des fichiers de pg_wal à la main corrompt l’instance. On identifie le consommateur, on supprime le slot s’il est abandonné (pg_drop_replication_slot) et on borne la rétention.","difficulty":"expert","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"32c43641-0c7a-5303-95c3-06f97cc4bd2b","type":"single","prompt":"L’application ouvre une nouvelle connexion PostgreSQL par requête et le serveur sature. Quelle solution est la plus adaptée ?","choices":[{"id":"a","text":"Désactiver l’authentification"},{"id":"b","text":"Un pool de connexions (dans l’application ou PgBouncer), plutôt qu’augmenter fortement max_connections"},{"id":"c","text":"Passer max_connections à 10 000"},{"id":"d","text":"Redémarrer PostgreSQL toutes les heures"}],"answer":["b"],"explanation":"Chaque connexion PostgreSQL est un processus qui coûte de la mémoire et du temps à ouvrir. Un pool réutilise un petit nombre de connexions. Monter max_connections très haut dégrade les performances et peut épuiser la mémoire.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"0ae7a9ae-11c2-52f6-a089-ed42ef118ff5","type":"single","prompt":"Pourquoi ne pas régler `shared_buffers` à 90 % de la mémoire du serveur ?","choices":[{"id":"a","text":"Parce que PostgreSQL s’appuie aussi sur le cache du système, et que les connexions, les tris (work_mem) et l’OS ont besoin de mémoire ; on part souvent d’environ 25 %"},{"id":"b","text":"Parce que PostgreSQL refuse toute valeur supérieure à 1 Go"},{"id":"c","text":"Parce que la mémoire partagée est toujours lente"},{"id":"d","text":"Parce que shared_buffers ne sert à rien"}],"answer":["a"],"explanation":"Les données passent par le cache de PostgreSQL et par celui du noyau. Lui donner presque toute la mémoire laisse le système et les opérations de tri à court, avec un risque d’OOM. On ajuste ensuite selon les mesures (taux de cache, pg_stat_bgwriter).","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"60c3fbe2-9b6b-50b6-99b4-252e77701e9d","type":"single","prompt":"Une requête de rapport effectue un tri de plusieurs millions de lignes qui déborde sur disque (« external merge »). Quel réglage aide, avec prudence ?","choices":[{"id":"a","text":"Augmenter work_mem pour cette session ou ce rôle, en gardant en tête qu’il s’applique par opération et par connexion"},{"id":"b","text":"Réduire shared_buffers"},{"id":"c","text":"Désactiver les index"},{"id":"d","text":"Augmenter work_mem à 8 Go pour toute l’instance"}],"answer":["a"],"explanation":"work_mem fixe la mémoire d’un tri ou d’un hachage, et une requête peut en utiliser plusieurs, sur chaque connexion. Une valeur globale élevée peut épuiser la mémoire. On l’augmente localement (SET work_mem pour la session du rapport) ou par rôle.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"2dd69991-934e-5ade-b3ab-5775ee18ab24","type":"single","prompt":"Que règle le fichier pg_hba.conf ?","choices":[{"id":"a","text":"Le format des sauvegardes"},{"id":"b","text":"Qui peut se connecter, à quelle base, depuis quelles adresses et avec quelle méthode d’authentification"},{"id":"c","text":"La mémoire allouée à PostgreSQL"},{"id":"d","text":"Les droits sur les tables"}],"answer":["b"],"explanation":"pg_hba.conf filtre les connexions avant toute requête : la première ligne qui correspond s’applique. Les droits sur les objets se gèrent ensuite par GRANT. On évite trust, on préfère scram-sha-256, et on recharge la configuration après modification.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"9843bdf3-25ae-5a21-bd23-8986bced9ba1","type":"multiple","prompt":"Cochez les bonnes pratiques pour le compte utilisé par une application web.","choices":[{"id":"a","text":"Un rôle dédié, qui n’est ni superutilisateur ni propriétaire du schéma"},{"id":"b","text":"Le même mot de passe que celui de l’administrateur"},{"id":"c","text":"Des droits limités aux tables et opérations dont l’application a besoin"},{"id":"d","text":"Le compte postgres, pour éviter les erreurs de droits"}],"answer":["a","c"],"explanation":"Si l’application est compromise (injection SQL par exemple), les dégâts sont limités à ses propres droits. Un superutilisateur peut lire des fichiers du serveur, voire exécuter des commandes. Les migrations de schéma passent par un autre rôle.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"41c111c0-8849-50b5-8d68-64df180d66c9","type":"single","prompt":"Des requêtes restent bloquées et `pg_stat_activity` montre `wait_event_type = Lock`. Comment trouver qui les bloque ?","choices":[{"id":"a","text":"Avec pg_blocking_pids(pid) sur les sessions en attente, puis examiner la session bloquante dans pg_stat_activity"},{"id":"b","text":"Avec VACUUM ANALYZE"},{"id":"c","text":"En supprimant les index de la table"},{"id":"d","text":"En redémarrant PostgreSQL"}],"answer":["a"],"explanation":"pg_blocking_pids donne les processus qui détiennent le verrou attendu. Souvent, une transaction restée ouverte ou une migration (ALTER TABLE) en est la cause. On comprend avant d’agir ; pg_cancel_backend puis pg_terminate_backend en dernier recours.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"500c8d42-df28-5e8f-a094-c62b6c666677","type":"single","prompt":"Un `ALTER TABLE … ADD COLUMN` sur une table très lue reste bloqué derrière une longue requête, et toutes les requêtes suivantes se mettent à attendre derrière lui. Comment éviter cela ?","choices":[{"id":"a","text":"Lancer la migration sans transaction"},{"id":"b","text":"Fixer un lock_timeout court pour la migration et la relancer jusqu’à obtenir le verrou, plutôt que de laisser la file d’attente s’allonger"},{"id":"c","text":"Désactiver l’autovacuum"},{"id":"d","text":"Augmenter max_connections"}],"answer":["b"],"explanation":"L’ALTER TABLE demande un verrou exclusif ; en l’attendant, il bloque aussi les requêtes arrivées après lui. Avec un lock_timeout de quelques secondes, il échoue vite au lieu de paralyser la table, et on réessaie à un moment plus calme.","difficulty":"expert","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"2edd6e60-755f-5d73-898a-7be3f55f8f46","type":"single","prompt":"Quelle démarche suivre pour passer de PostgreSQL 14 à 17 sur une base importante ?","choices":[{"id":"a","text":"Tester la montée de version (pg_upgrade ou réplication logique) sur une copie, vérifier l’application, prévoir le retour arrière, puis migrer"},{"id":"b","text":"Installer la version 17 par-dessus et redémarrer"},{"id":"c","text":"Copier le répertoire de données de la 14 dans celui de la 17"},{"id":"d","text":"Exporter avec pg_dump sans tester la restauration"}],"answer":["a"],"explanation":"Le format des fichiers change entre versions majeures : il faut pg_upgrade, un dump et une restauration, ou la réplication logique. Les extensions et certaines requêtes peuvent se comporter différemment ; la répétition sur une copie révèle ces surprises et la durée réelle.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"1483c9fd-a1c1-5417-a05e-9da26ae9f7c5","type":"single","prompt":"À quoi sert l’extension pg_stat_statements ?","choices":[{"id":"a","text":"À agréger les statistiques des requêtes normalisées (nombre d’appels, temps total et moyen), pour repérer celles qui coûtent le plus"},{"id":"b","text":"À sauvegarder les requêtes pour les rejouer après une panne"},{"id":"c","text":"À bloquer les requêtes lentes"},{"id":"d","text":"À chiffrer les requêtes"}],"answer":["a"],"explanation":"Une requête rapide exécutée un million de fois peut coûter plus qu’une requête lente rare. pg_stat_statements trie par temps total et oriente l’optimisation. Elle mesure, elle ne bloque ni ne rejoue rien.","difficulty":"advanced","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"d6e9429d-d407-57a3-b0d5-8340925add0f","type":"single","prompt":"Pourquoi le partitionnement d’une table de journaux par mois facilite-t-il la purge des anciennes données ?","choices":[{"id":"a","text":"Parce qu’on détache ou supprime une partition entière en un instant, au lieu d’un DELETE massif qui génère des lignes mortes et beaucoup de WAL"},{"id":"b","text":"Parce que les partitions se suppriment toutes seules"},{"id":"c","text":"Parce que DELETE est interdit sur une table partitionnée"},{"id":"d","text":"Parce que les données partitionnées ne prennent pas de place"}],"answer":["a"],"explanation":"DROP ou DETACH PARTITION sont des opérations rapides sur les métadonnées. Un DELETE de millions de lignes crée autant de versions mortes à nettoyer et une charge d’écriture importante. Les requêtes filtrées sur la date ne lisent en plus que les partitions utiles.","difficulty":"intermediate","platform":"postgresql"}$q$::jsonb),
    ($q${"id":"5cb98ad5-c2a7-5e02-a9e4-9ef550d8a040","type":"single","prompt":"Des alertes signalent que l’âge des identifiants de transaction (age(datfrozenxid)) d’une base approche 1,5 milliard. Quel est le risque, et que faire ?","choices":[{"id":"a","text":"À l’approche de la limite, PostgreSQL refuse de nouvelles transactions pour protéger les données : il faut identifier ce qui bloque le gel (transaction ancienne, slot, table non vacuumée) et lancer un VACUUM des tables concernées"},{"id":"b","text":"Il faut augmenter max_connections"},{"id":"c","text":"Aucun risque, ce compteur est purement informatif"},{"id":"d","text":"Il faut réinitialiser le compteur avec pg_resetwal"}],"answer":["a"],"explanation":"Les identifiants de transaction sur 32 bits rebouclent ; le gel des lignes anciennes par VACUUM l’évite. Si quelque chose empêche ce gel, la base finit par se protéger en refusant les écritures. pg_resetwal est un outil de dernier recours qui peut perdre des données.","difficulty":"expert","platform":"postgresql"}$q$::jsonb)
  ) AS v(q)
ON CONFLICT (id) DO UPDATE
  SET type = EXCLUDED.type, prompt_md = EXCLUDED.prompt_md, choices = EXCLUDED.choices, answer = EXCLUDED.answer,
      explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, platform = EXCLUDED.platform;

-- Réglages des examens dont la banque est prête.
UPDATE assessment.certifications c SET exam_question_count = e.n, exam_time_limit_s = e.t, exam_difficulties = e.d::platform.difficulty[]
  FROM (VALUES
    ('LINUX-ADMIN', 10, 1200, '{beginner,intermediate}'),
    ('LINUX-EXPERT', 20, 1800, '{advanced,expert}'),
    ('NET-SPEC', 15, 1500, '{}'),
    ('DOCKER-SPEC', 15, 1500, '{}'),
    ('CYBER-SPEC', 15, 1500, '{}'),
    ('WIN-TECH', 15, 1500, '{beginner,intermediate}'),
    ('WIN-ADMIN', 20, 1800, '{intermediate,advanced,expert}'),
    ('DEVOPS-SPEC', 20, 1800, '{}'),
    ('PG-SPEC', 20, 1800, '{}'),
    ('SYSMASTER-EXPERT', 40, 3600, '{advanced,expert}')
  ) AS e(code, n, t, d)
 WHERE c.code = e.code;

